import { FormEvent, useEffect, useState } from 'react';
import { inventaireApi, marchandisesApi, produitsApi } from '../lib/api';
import type { InventaireMagasin, Marchandise, Produit } from '../types';

export function AddProduitForm({ onAdded }: { onAdded?: () => void }) {
  const [nom, setNom] = useState('');
  const [categorie, setCategorie] = useState('');
  const [prix, setPrix] = useState('');
  const [unite, setUnite] = useState('unité');
  const [description, setDescription] = useState('');
  const [error, setError] = useState('');

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    setError('');
    try {
      await produitsApi.create({
        nom,
        categorie,
        prix: Number(prix),
        unite,
        description: description || undefined,
      });
      setNom('');
      setCategorie('');
      setPrix('');
      setUnite('unité');
      setDescription('');
      onAdded?.();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  return (
    <form onSubmit={handleSubmit} className="add-form">
      {error && <p className="error-text">{error}</p>}
      <label>
        Nom
        <input value={nom} onChange={(e) => setNom(e.target.value)} required />
      </label>
      <label>
        Catégorie
        <input value={categorie} onChange={(e) => setCategorie(e.target.value)} required />
      </label>
      <label>
        Prix (€)
        <input
          type="number"
          min="0"
          step="0.01"
          value={prix}
          onChange={(e) => setPrix(e.target.value)}
          required
        />
      </label>
      <label>
        Unité
        <input value={unite} onChange={(e) => setUnite(e.target.value)} />
      </label>
      <label>
        Description
        <input value={description} onChange={(e) => setDescription(e.target.value)} />
      </label>
      <button type="submit" className="btn btn-primary">Ajouter le produit</button>
    </form>
  );
}

export function AddMarchandiseForm({ onAdded }: { onAdded?: () => void }) {
  const [nom, setNom] = useState('');
  const [categorie, setCategorie] = useState('');
  const [unite, setUnite] = useState('kg');
  const [quantite, setQuantite] = useState(0);
  const [error, setError] = useState('');

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    setError('');
    try {
      await marchandisesApi.create({ nom, categorie, unite, quantite });
      setNom('');
      setCategorie('');
      setUnite('kg');
      setQuantite(0);
      onAdded?.();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  return (
    <form onSubmit={handleSubmit} className="add-form">
      {error && <p className="error-text">{error}</p>}
      <label>
        Nom
        <input value={nom} onChange={(e) => setNom(e.target.value)} required />
      </label>
      <label>
        Catégorie
        <input value={categorie} onChange={(e) => setCategorie(e.target.value)} required />
      </label>
      <label>
        Unité
        <input value={unite} onChange={(e) => setUnite(e.target.value)} />
      </label>
      <label>
        Quantité initiale
        <input
          type="number"
          min="0"
          step="0.1"
          value={quantite}
          onChange={(e) => setQuantite(Number(e.target.value))}
        />
      </label>
      <button type="submit" className="btn btn-primary">Ajouter la marchandise</button>
    </form>
  );
}

export function AddInventaireForm({
  magasinId,
  existingProduitIds,
  onAdded,
}: {
  magasinId: string;
  existingProduitIds: string[];
  onAdded?: (item: InventaireMagasin) => void;
}) {
  const [produits, setProduits] = useState<Produit[]>([]);
  const [produitId, setProduitId] = useState('');
  const [quantite, setQuantite] = useState(0);
  const [seuilAlerte, setSeuilAlerte] = useState(5);
  const [error, setError] = useState('');

  useEffect(() => {
    produitsApi
      .list()
      .then((items) => {
        const available = items.filter((p) => !existingProduitIds.includes(p.id));
        setProduits(available);
        if (available.length > 0) setProduitId(available[0].id);
      })
      .catch((err) => setError(err.message));
  }, [existingProduitIds]);

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    if (!produitId) {
      setError('Aucun produit disponible à ajouter');
      return;
    }
    setError('');
    try {
      const item = await inventaireApi.update(produitId, {
        magasinId,
        quantite,
        seuilAlerte,
      });
      setQuantite(0);
      setSeuilAlerte(5);
      onAdded?.(item);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  if (produits.length === 0) {
    return <p className="muted">Tous les produits sont déjà dans l'inventaire.</p>;
  }

  return (
    <form onSubmit={handleSubmit} className="add-form">
      {error && <p className="error-text">{error}</p>}
      <label>
        Produit
        <select value={produitId} onChange={(e) => setProduitId(e.target.value)} required>
          {produits.map((p) => (
            <option key={p.id} value={p.id}>
              {p.nom} ({p.categorie})
            </option>
          ))}
        </select>
      </label>
      <label>
        Quantité initiale
        <input
          type="number"
          min="0"
          step="1"
          value={quantite}
          onChange={(e) => setQuantite(Number(e.target.value))}
        />
      </label>
      <label>
        Seuil d'alerte
        <input
          type="number"
          min="0"
          step="1"
          value={seuilAlerte}
          onChange={(e) => setSeuilAlerte(Number(e.target.value))}
        />
      </label>
      <button type="submit" className="btn btn-primary">Ajouter à l'inventaire</button>
    </form>
  );
}

:root {
  --bg: #f4f7fb;
  --bg-warm: #faf8f5;
  --panel: #ffffff;
  --text: #3d3229;
  --muted: #7a6f63;
  --primary: #2563eb;
  --primary-dark: #1d4ed8;
  --primary-light: #dbeafe;
  --brown: #8b6f47;
  --brown-light: #c4a882;
  --brown-dark: #5c4a32;
  --sidebar-from: #1e40af;
  --sidebar-to: #3d2e24;
  --border: #d4e4f7;
  --border-warm: #e8dfd4;
  --alert: #dc2626;
  --success: #15803d;
  --shadow: 0 10px 30px rgba(30, 64, 175, 0.08);
  font-family: 'Source Sans 3', sans-serif;
  color: var(--text);
  background: var(--bg);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(circle at top left, rgba(37, 99, 235, 0.06), transparent 35%),
    radial-gradient(circle at bottom right, rgba(139, 111, 71, 0.05), transparent 30%),
    var(--bg);
}

h1, h2, h3, strong {
  font-family: 'Cormorant Garamond', serif;
  color: var(--brown-dark);
}

a {
  color: inherit;
  text-decoration: none;
}

.app-shell {
  display: grid;
  grid-template-columns: 280px 1fr;
  min-height: 100vh;
}

.sidebar {
  background: linear-gradient(180deg, var(--sidebar-from) 0%, var(--sidebar-to) 100%);
  color: #f8fafc;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.brand {
  display: flex;
  gap: 0.75rem;
  align-items: center;
}

.brand strong {
  display: block;
  font-size: 1.35rem;
  color: #ffffff;
}

.brand small {
  color: var(--brown-light);
}

.brand-icon {
  font-size: 1.8rem;
}

.brand-icon.large {
  font-size: 3rem;
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.sidebar-nav a {
  padding: 0.75rem 1rem;
  border-radius: 12px;
  color: #dbeafe;
}

.sidebar-nav a.active,
.sidebar-nav a:hover {
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
}

.sidebar-footer {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.user-card {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.user-card strong {
  color: #ffffff;
}

.user-card span,
.user-card small {
  color: var(--brown-light);
}

.main-content {
  padding: 2rem;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.page-header h1 {
  margin: 0;
  font-size: 2.4rem;
}

.page-header p {
  margin: 0.35rem 0 0;
  color: var(--muted);
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border-warm);
  border-radius: 18px;
  padding: 1.25rem;
  box-shadow: var(--shadow);
}

.panel h2 {
  margin-top: 0;
}

.stats-grid,
.grid-2,
.product-order-grid,
.quick-add-grid {
  display: grid;
  gap: 1rem;
}

.stats-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 1.5rem;
}

.grid-2 {
  grid-template-columns: 1.4fr 1fr;
}

.quick-add-grid {
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  margin-bottom: 1.5rem;
}

.stat-card {
  background: var(--panel);
  border: 1px solid var(--border-warm);
  border-radius: 16px;
  padding: 1.2rem;
  box-shadow: var(--shadow);
}

.stat-card-alert {
  border-color: #fecaca;
  background: #fff5f5;
}

.stat-label {
  display: block;
  color: var(--muted);
  margin-bottom: 0.35rem;
}

.stat-value {
  font-size: 2rem;
  font-family: 'Cormorant Garamond', serif;
  color: var(--primary);
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  padding: 0.85rem 0.75rem;
  border-bottom: 1px solid var(--border-warm);
  text-align: left;
  vertical-align: top;
}

th {
  color: var(--muted);
  font-size: 0.9rem;
}

.row-alert {
  background: #eff6ff;
}

.btn {
  border: none;
  border-radius: 12px;
  padding: 0.75rem 1.1rem;
  font: inherit;
  cursor: pointer;
  transition: 0.2s ease;
}

.btn-primary {
  background: var(--primary);
  color: white;
}

.btn-primary:hover {
  background: var(--primary-dark);
}

.btn-secondary {
  background: var(--primary-light);
  color: var(--primary-dark);
}

.btn-secondary:hover {
  background: #bfdbfe;
}

.btn-ghost {
  background: transparent;
  color: #dbeafe;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.btn-sm {
  padding: 0.45rem 0.75rem;
  font-size: 0.85rem;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

label {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin-bottom: 1rem;
  font-weight: 600;
}

input,
textarea,
select {
  font: inherit;
  padding: 0.75rem 0.85rem;
  border: 1px solid var(--border-warm);
  border-radius: 12px;
  background: white;
}

input:focus,
textarea:focus,
select:focus {
  outline: 2px solid var(--primary-light);
  border-color: var(--primary);
}

.form-panel form,
.add-form {
  max-width: 100%;
}

.badge {
  display: inline-block;
  padding: 0.25rem 0.65rem;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 600;
}

.badge-en_attente { background: #fef3c7; color: #92400e; }
.badge-en_preparation { background: #dbeafe; color: #1d4ed8; }
.badge-expediee { background: #e0e7ff; color: #4338ca; }
.badge-livree { background: #dcfce7; color: #166534; }
.badge-annulee { background: #fee2e2; color: #991b1b; }

.alert-list,
.inline-list,
.mini-list ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.alert-item {
  padding: 0.8rem 0;
  border-bottom: 1px solid var(--border-warm);
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.inline-list li {
  margin-bottom: 0.25rem;
}

.login-page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 1rem;
  background:
    radial-gradient(circle at top right, rgba(37, 99, 235, 0.12), transparent 35%),
    radial-gradient(circle at bottom left, rgba(139, 111, 71, 0.1), transparent 30%),
    linear-gradient(180deg, #ffffff, #f4f7fb);
}

.login-card {
  width: min(100%, 480px);
  background: white;
  border: 1px solid var(--border-warm);
  border-radius: 24px;
  padding: 2rem;
  box-shadow: var(--shadow);
}

.login-header {
  text-align: center;
  margin-bottom: 1.5rem;
}

.login-header h1 {
  margin: 0.5rem 0 0.25rem;
}

.login-header p,
.demo-accounts p,
.muted {
  color: var(--muted);
}

.demo-accounts {
  margin-top: 1.5rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border-warm);
  font-size: 0.92rem;
}

.demo-accounts ul {
  padding-left: 1.1rem;
}

.error-text {
  color: var(--alert);
}

.loading-screen {
  min-height: 100vh;
  display: grid;
  place-items: center;
}

.product-order-grid {
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  margin-bottom: 1rem;
}

.product-order-card {
  border: 1px solid var(--border-warm);
  border-radius: 14px;
  padding: 1rem;
  background: var(--bg-warm);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.product-order-card span {
  color: var(--muted);
  font-size: 0.9rem;
}

@media (max-width: 960px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: sticky;
    top: 0;
    z-index: 10;
  }

  .stats-grid,
  .grid-2,
  .quick-add-grid {
    grid-template-columns: 1fr;
  }
}

