import { useEffect, useState } from 'react';
import { stockApi } from '../lib/api';
import { AddProduitForm } from '../components/AddForms';
import { PageHeader } from '../components/UI';
import type { StockProduit } from '../types';

export function StockProductionPage() {
  const [stock, setStock] = useState<StockProduit[]>([]);
  const [error, setError] = useState('');

  async function load() {
    setStock(await stockApi.produits());
  }

  useEffect(() => {
    load().catch((err) => setError(err.message));
  }, []);

  async function updateQuantite(produitId: string, quantite: number) {
    try {
      const updated = await stockApi.updateProduit(produitId, { quantite });
      setStock((items) => items.map((item) => (item.produitId === produitId ? updated : item)));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  return (
    <>
      <PageHeader
        title="Stock production — Produits finis"
        subtitle="Quantités disponibles au centre de production"
      />

      {error && <p className="error-text">{error}</p>}

      <div className="grid-2">
        <section className="panel">
          <h2>Stock actuel</h2>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Produit</th>
                  <th>Catégorie</th>
                  <th>Quantité</th>
                  <th>Seuil d'alerte</th>
                  <th>État</th>
                </tr>
              </thead>
              <tbody>
                {stock.map((item) => {
                  const lowStock = item.quantite <= item.seuilAlerte;
                  return (
                    <tr key={item.id} className={lowStock ? 'row-alert' : ''}>
                      <td><strong>{item.produit.nom}</strong></td>
                      <td>{item.produit.categorie}</td>
                      <td>
                        <input
                          type="number"
                          min="0"
                          value={item.quantite}
                          onChange={(e) => updateQuantite(item.produitId, Number(e.target.value))}
                        />
                      </td>
                      <td>{item.seuilAlerte}</td>
                      <td>{lowStock ? '⚠️ Stock bas' : 'OK'}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </section>

        <section className="panel form-panel">
          <h2>Ajouter un produit</h2>
          <AddProduitForm onAdded={() => load().catch((err) => setError(err.message))} />
        </section>
      </div>
    </>
  );
}

import { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { inventaireApi } from '../lib/api';
import { AddInventaireForm } from '../components/AddForms';
import { PageHeader } from '../components/UI';
import type { InventaireMagasin } from '../types';

export function InventairePage() {
  const { user } = useAuth();
  const [inventaires, setInventaires] = useState<InventaireMagasin[]>([]);
  const [error, setError] = useState('');
  const [savingId, setSavingId] = useState<string | null>(null);

  const magasinId = user?.magasinId;

  async function load() {
    if (!magasinId) return;
    setInventaires(await inventaireApi.list(magasinId));
  }

  useEffect(() => {
    load().catch((err) => setError(err.message));
  }, [magasinId]);

  async function updateQuantite(produitId: string, quantite: number) {
    if (!magasinId) return;

    setSavingId(produitId);
    try {
      const updated = await inventaireApi.update(produitId, { magasinId, quantite });
      setInventaires((items) =>
        items.map((item) => (item.produitId === produitId ? updated : item)),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setSavingId(null);
    }
  }

  function handleAdded(item: InventaireMagasin) {
    setInventaires((items) => [...items, item].sort((a, b) => a.produit.nom.localeCompare(b.produit.nom)));
  }

  return (
    <>
      <PageHeader
        title="Inventaire du magasin"
        subtitle="Mettez à jour les quantités disponibles en boutique"
      />

      {error && <p className="error-text">{error}</p>}

      <div className="grid-2">
        <section className="panel">
          <h2>Produits en boutique</h2>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Produit</th>
                  <th>Catégorie</th>
                  <th>Quantité</th>
                  <th>Seuil d'alerte</th>
                  <th>État</th>
                </tr>
              </thead>
              <tbody>
                {inventaires.map((item) => {
                  const lowStock = item.quantite <= item.seuilAlerte;
                  return (
                    <tr key={item.id} className={lowStock ? 'row-alert' : ''}>
                      <td>
                        <strong>{item.produit.nom}</strong>
                        <small>{item.produit.unite}</small>
                      </td>
                      <td>{item.produit.categorie}</td>
                      <td>
                        <input
                          type="number"
                          min="0"
                          step="1"
                          value={item.quantite}
                          onChange={(e) =>
                            updateQuantite(item.produitId, Number(e.target.value))
                          }
                          disabled={savingId === item.produitId}
                        />
                      </td>
                      <td>{item.seuilAlerte}</td>
                      <td>{lowStock ? '⚠️ Stock bas' : 'OK'}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </section>

        <section className="panel form-panel">
          <h2>Ajouter un article</h2>
          {magasinId && (
            <AddInventaireForm
              magasinId={magasinId}
              existingProduitIds={inventaires.map((i) => i.produitId)}
              onAdded={handleAdded}
            />
          )}
        </section>
      </div>
    </>
  );
}

import { FormEvent, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { marchandisesApi, stockApi } from '../lib/api';
import { AddMarchandiseForm } from '../components/AddForms';
import { PageHeader } from '../components/UI';
import type { Marchandise, StockMarchandise } from '../types';

export function MarchandisesPage() {
  const [marchandises, setMarchandises] = useState<Marchandise[]>([]);
  const [stock, setStock] = useState<StockMarchandise[]>([]);
  const [error, setError] = useState('');

  async function load() {
    const [items, stockItems] = await Promise.all([
      marchandisesApi.list(),
      stockApi.marchandises(),
    ]);
    setMarchandises(items);
    setStock(stockItems);
  }

  useEffect(() => {
    load().catch((err) => setError(err.message));
  }, []);

  async function updateQuantite(marchandiseId: string, value: number) {
    try {
      const updated = await stockApi.updateMarchandise(marchandiseId, { quantite: value });
      setStock((items) =>
        items.map((item) => (item.marchandiseId === marchandiseId ? updated : item)),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  return (
    <>
      <PageHeader
        title="Marchandises & matières premières"
        subtitle="Gestion du stock au centre de production"
      />

      {error && <p className="error-text">{error}</p>}

      <div className="grid-2">
        <section className="panel">
          <h2>Stock des marchandises</h2>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Nom</th>
                  <th>Catégorie</th>
                  <th>Quantité</th>
                  <th>Unité</th>
                </tr>
              </thead>
              <tbody>
                {stock.map((item) => (
                  <tr key={item.id}>
                    <td><strong>{item.marchandise.nom}</strong></td>
                    <td>{item.marchandise.categorie}</td>
                    <td>
                      <input
                        type="number"
                        min="0"
                        step="0.1"
                        value={item.quantite}
                        onChange={(e) =>
                          updateQuantite(item.marchandiseId, Number(e.target.value))
                        }
                      />
                    </td>
                    <td>{item.marchandise.unite}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

        <section className="panel form-panel">
          <h2>Ajouter une marchandise</h2>
          <AddMarchandiseForm onAdded={() => load().catch((err) => setError(err.message))} />

          <div className="mini-list">
            <h3>Références actives</h3>
            <ul>
              {marchandises.map((item) => (
                <li key={item.id}>{item.nom} ({item.categorie})</li>
              ))}
            </ul>
          </div>
        </section>
      </div>
    </>
  );
}

import { FormEvent, useEffect, useState } from 'react';
import { inventaireApi, magasinsApi } from '../lib/api';
import { PageHeader } from '../components/UI';
import type { Magasin } from '../types';

export function MagasinsPage() {
  const [magasins, setMagasins] = useState<Magasin[]>([]);
  const [nom, setNom] = useState('');
  const [adresse, setAdresse] = useState('');
  const [telephone, setTelephone] = useState('');
  const [error, setError] = useState('');
  const [initId, setInitId] = useState<string | null>(null);

  async function load() {
    try {
      setMagasins(await magasinsApi.list());
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  useEffect(() => {
    load();
  }, []);

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    try {
      await magasinsApi.create({ nom, adresse, telephone: telephone || undefined });
      setNom('');
      setAdresse('');
      setTelephone('');
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  async function initialiserInventaire(magasinId: string) {
    setInitId(magasinId);
    try {
      await inventaireApi.initialiser(magasinId);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setInitId(null);
    }
  }

  return (
    <>
      <PageHeader title="Magasins" subtitle="Gestion des points de vente" />

      {error && <p className="error-text">{error}</p>}

      <div className="grid-2">
        <section className="panel">
          <h2>Liste des magasins</h2>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Nom</th>
                  <th>Adresse</th>
                  <th>Téléphone</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {magasins.map((magasin) => (
                  <tr key={magasin.id}>
                    <td><strong>{magasin.nom}</strong></td>
                    <td>{magasin.adresse}</td>
                    <td>{magasin.telephone || '—'}</td>
                    <td>
                      <button
                        type="button"
                        className="btn btn-secondary btn-sm"
                        disabled={initId === magasin.id}
                        onClick={() => initialiserInventaire(magasin.id)}
                      >
                        {initId === magasin.id ? '...' : 'Sync inventaire'}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

        <section className="panel form-panel">
          <h2>Ajouter un magasin</h2>
          <form onSubmit={handleSubmit} className="add-form">
            <label>
              Nom
              <input value={nom} onChange={(e) => setNom(e.target.value)} required />
            </label>
            <label>
              Adresse
              <input value={adresse} onChange={(e) => setAdresse(e.target.value)} required />
            </label>
            <label>
              Téléphone
              <input value={telephone} onChange={(e) => setTelephone(e.target.value)} />
            </label>
            <button type="submit" className="btn btn-primary">Créer le magasin</button>
          </form>
        </section>
      </div>
    </>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { commandesApi } from '../lib/api';
import { PageHeader, StatusBadge } from '../components/UI';
import type { Commande, StatutCommande } from '../types';

const nextStatut: Partial<Record<StatutCommande, StatutCommande>> = {
  EN_ATTENTE: 'EN_PREPARATION',
  EN_PREPARATION: 'EXPEDIEE',
  EXPEDIEE: 'LIVREE',
};

export function CommandesPage() {
  const { user } = useAuth();
  const [commandes, setCommandes] = useState<Commande[]>([]);
  const [error, setError] = useState('');
  const [loadingId, setLoadingId] = useState<string | null>(null);

  useEffect(() => {
    commandesApi
      .list()
      .then(setCommandes)
      .catch((err) => setError(err.message));
  }, []);

  async function advanceStatut(commande: Commande) {
    const next = nextStatut[commande.statut];
    if (!next) return;

    setLoadingId(commande.id);
    try {
      const updated = await commandesApi.updateStatut(commande.id, next);
      setCommandes((items) => items.map((item) => (item.id === updated.id ? updated : item)));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setLoadingId(null);
    }
  }

  return (
    <>
      <PageHeader
        title={user?.role === 'MAGASIN' ? 'Mes commandes' : 'Commandes reçues'}
        subtitle={
          user?.role === 'PRODUCTION'
            ? 'Les commandes des magasins arrivent directement ici'
            : 'Suivi des commandes envoyées au centre de production'
        }
        action={
          user?.role === 'MAGASIN' ? (
            <Link to="/nouvelle-commande" className="btn btn-primary">
              Nouvelle commande
            </Link>
          ) : undefined
        }
      />

      {error && <p className="error-text">{error}</p>}

      <section className="panel">
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Numéro</th>
                {user?.role !== 'MAGASIN' && <th>Magasin</th>}
                <th>Date</th>
                <th>Produits</th>
                <th>Statut</th>
                {user?.role !== 'MAGASIN' && <th>Action</th>}
              </tr>
            </thead>
            <tbody>
              {commandes.map((commande) => (
                <tr key={commande.id}>
                  <td><strong>{commande.numero}</strong></td>
                  {user?.role !== 'MAGASIN' && <td>{commande.magasin?.nom}</td>}
                  <td>{new Date(commande.createdAt).toLocaleString('fr-FR')}</td>
                  <td>
                    <ul className="inline-list">
                      {commande.lignes.map((ligne) => (
                        <li key={ligne.id}>
                          {ligne.quantite} × {ligne.produit.nom}
                        </li>
                      ))}
                    </ul>
                  </td>
                  <td><StatusBadge statut={commande.statut} /></td>
                  {user?.role !== 'MAGASIN' && (
                    <td>
                      {nextStatut[commande.statut] ? (
                        <button
                          type="button"
                          className="btn btn-secondary btn-sm"
                          disabled={loadingId === commande.id}
                          onClick={() => advanceStatut(commande)}
                        >
                          → {nextStatut[commande.statut]}
                        </button>
                      ) : (
                        '—'
                      )}
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { commandesApi, dashboardApi } from '../lib/api';
import { AddInventaireForm, AddMarchandiseForm, AddProduitForm } from '../components/AddForms';
import { PageHeader, StatCard, StatusBadge } from '../components/UI';
import type { Commande, DashboardData } from '../types';

export function DashboardPage() {
  const { user } = useAuth();
  const [dashboard, setDashboard] = useState<DashboardData | null>(null);
  const [mesCommandes, setMesCommandes] = useState<Commande[]>([]);
  const [error, setError] = useState('');

  useEffect(() => {
    async function load() {
      try {
        if (user?.role === 'MAGASIN') {
          const commandes = await commandesApi.list();
          setMesCommandes(commandes.slice(0, 5));
        } else {
          const data = await dashboardApi.get();
          setDashboard(data);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Erreur de chargement');
      }
    }

    load();
  }, [user]);

  if (user?.role === 'MAGASIN') {
    return (
      <>
        <PageHeader
          title={`Bonjour, ${user.nom}`}
          subtitle={user.magasin ? `Magasin : ${user.magasin.nom}` : undefined}
          action={
            <Link to="/nouvelle-commande" className="btn btn-primary">
              Nouvelle commande
            </Link>
          }
        />

        {error && <p className="error-text">{error}</p>}

        <div className="quick-add-grid">
          <section className="panel form-panel">
            <h2>Ajouter un article à l'inventaire</h2>
            {user.magasinId && (
              <AddInventaireForm magasinId={user.magasinId} existingProduitIds={[]} />
            )}
          </section>
        </div>

        <section className="panel">
          <h2>Dernières commandes</h2>
          {mesCommandes.length === 0 ? (
            <p className="muted">Aucune commande pour le moment.</p>
          ) : (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>Numéro</th>
                    <th>Date</th>
                    <th>Statut</th>
                  </tr>
                </thead>
                <tbody>
                  {mesCommandes.map((commande) => (
                    <tr key={commande.id}>
                      <td>{commande.numero}</td>
                      <td>{new Date(commande.createdAt).toLocaleDateString('fr-FR')}</td>
                      <td><StatusBadge statut={commande.statut} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </>
    );
  }

  return (
    <>
      <PageHeader
        title="Tableau de bord global"
        subtitle="Vue d'ensemble des magasins, commandes et stocks"
      />

      {error && <p className="error-text">{error}</p>}

      <div className="quick-add-grid">
        <section className="panel form-panel">
          <h2>Ajouter un produit</h2>
          <AddProduitForm />
        </section>
        <section className="panel form-panel">
          <h2>Ajouter une marchandise</h2>
          <AddMarchandiseForm />
        </section>
        {user?.role === 'ADMIN' && (
          <section className="panel form-panel">
            <h2>Ajouter un magasin</h2>
            <p className="muted">Gérez les magasins depuis l'onglet dédié.</p>
            <Link to="/magasins" className="btn btn-primary">Aller aux magasins</Link>
          </section>
        )}
      </div>

      {dashboard && (
        <>
          <div className="stats-grid">
            <StatCard label="Magasins actifs" value={dashboard.stats.magasinsActifs} />
            <StatCard
              label="Commandes en attente"
              value={dashboard.stats.commandesEnAttente}
              alert={dashboard.stats.commandesEnAttente > 0}
            />
            <StatCard
              label="Alertes stock production"
              value={dashboard.stats.alertesStockProduction}
              alert={dashboard.stats.alertesStockProduction > 0}
            />
            <StatCard
              label="Alertes inventaire magasins"
              value={dashboard.stats.alertesInventaireMagasins}
              alert={dashboard.stats.alertesInventaireMagasins > 0}
            />
          </div>

          <div className="grid-2">
            <section className="panel">
              <h2>Commandes récentes</h2>
              <div className="table-wrap">
                <table>
                  <thead>
                    <tr>
                      <th>Numéro</th>
                      <th>Magasin</th>
                      <th>Statut</th>
                    </tr>
                  </thead>
                  <tbody>
                    {dashboard.commandesRecentes.map((commande) => (
                      <tr key={commande.id}>
                        <td>{commande.numero}</td>
                        <td>{commande.magasin?.nom}</td>
                        <td><StatusBadge statut={commande.statut} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>

            <section className="panel">
              <h2>Alertes</h2>
              <div className="alert-list">
                {dashboard.alertes.inventairesMagasins.slice(0, 5).map((item) => (
                  <div key={item.id} className="alert-item">
                    <strong>{item.produit.nom}</strong>
                    <span>{item.magasin?.nom ?? 'Magasin'} — {item.quantite} restants</span>
                  </div>
                ))}
                {dashboard.alertes.stockProduits.slice(0, 3).map((item) => (
                  <div key={item.id} className="alert-item">
                    <strong>Stock production : {item.produit.nom}</strong>
                    <span>{item.quantite} {item.produit.unite}</span>
                  </div>
                ))}
                {dashboard.alertes.stockMarchandises.slice(0, 3).map((item) => (
                  <div key={item.id} className="alert-item">
                    <strong>Matière : {item.marchandise.nom}</strong>
                    <span>{item.quantite} {item.marchandise.unite}</span>
                  </div>
                ))}
              </div>
            </section>
          </div>
        </>
      )}
    </>
  );
}

