export type ThemeId = 'delice' | 'boulangerie' | 'ocean' | 'sombre';

export const themeOptions: { id: ThemeId; label: string }[] = [
  { id: 'delice', label: 'Bleu & Brun' },
  { id: 'boulangerie', label: 'Boulangerie' },
  { id: 'ocean', label: 'Océan' },
  { id: 'sombre', label: 'Sombre' },
];

const STORAGE_PREFIX = 'theme';

function storageKey(userId?: string) {
  return userId ? `${STORAGE_PREFIX}:${userId}` : STORAGE_PREFIX;
}

export function loadStoredTheme(userId?: string): ThemeId {
  const stored = localStorage.getItem(storageKey(userId));
  if (stored && themeOptions.some((t) => t.id === stored)) {
    return stored as ThemeId;
  }
  return 'delice';
}

export function saveTheme(theme: ThemeId, userId?: string) {
  localStorage.setItem(storageKey(userId), theme);
}

export function applyTheme(theme: ThemeId) {
  document.documentElement.dataset.theme = theme;
}

import { createContext, useContext, useEffect, useState, type ReactNode } from 'react';
import { useAuth } from './AuthContext';
import {
  applyTheme,
  loadStoredTheme,
  saveTheme,
  themeOptions,
  type ThemeId,
} from '../lib/themes';

interface ThemeContextValue {
  theme: ThemeId;
  setTheme: (theme: ThemeId) => void;
  options: typeof themeOptions;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

export function ThemeProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [theme, setThemeState] = useState<ThemeId>(() => loadStoredTheme(user?.id));

  useEffect(() => {
    const stored = loadStoredTheme(user?.id);
    setThemeState(stored);
    applyTheme(stored);
  }, [user?.id]);

  function setTheme(next: ThemeId) {
    setThemeState(next);
    saveTheme(next, user?.id);
    applyTheme(next);
  }

  return (
    <ThemeContext.Provider value={{ theme, setTheme, options: themeOptions }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme doit être utilisé dans ThemeProvider');
  }
  return context;
}

import { useTheme } from '../context/ThemeContext';

export function ThemeSwitcher({ compact = false }: { compact?: boolean }) {
  const { theme, setTheme, options } = useTheme();

  return (
    <label className={`theme-switcher ${compact ? 'theme-switcher-compact' : ''}`}>
      {!compact && <span>Thème</span>}
      <select value={theme} onChange={(e) => setTheme(e.target.value as typeof theme)}>
        {options.map((option) => (
          <option key={option.id} value={option.id}>
            {option.label}
          </option>
        ))}
      </select>
    </label>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { commandesApi, dashboardApi } from '../lib/api';
import { PageHeader, StatCard, StatusBadge } from '../components/UI';
import type { Commande, DashboardData } from '../types';

export function DashboardPage() {
  const { user } = useAuth();
  const [dashboard, setDashboard] = useState<DashboardData | null>(null);
  const [mesCommandes, setMesCommandes] = useState<Commande[]>([]);
  const [error, setError] = useState('');

  useEffect(() => {
    async function load() {
      try {
        if (user?.role === 'MAGASIN') {
          const commandes = await commandesApi.list();
          setMesCommandes(commandes.slice(0, 5));
        } else {
          const data = await dashboardApi.get();
          setDashboard(data);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Erreur de chargement');
      }
    }

    load();
  }, [user]);

  if (user?.role === 'MAGASIN') {
    return (
      <>
        <PageHeader
          title={`Bonjour, ${user.nom}`}
          subtitle={user.magasin ? `Magasin : ${user.magasin.nom}` : undefined}
          action={
            <Link to="/nouvelle-commande" className="btn btn-primary">
              Nouvelle commande
            </Link>
          }
        />

        {error && <p className="error-text">{error}</p>}

        <section className="panel">
          <h2>Dernières commandes</h2>
          {mesCommandes.length === 0 ? (
            <p className="muted">Aucune commande pour le moment.</p>
          ) : (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>Numéro</th>
                    <th>Date</th>
                    <th>Statut</th>
                  </tr>
                </thead>
                <tbody>
                  {mesCommandes.map((commande) => (
                    <tr key={commande.id}>
                      <td>{commande.numero}</td>
                      <td>{new Date(commande.createdAt).toLocaleDateString('fr-FR')}</td>
                      <td><StatusBadge statut={commande.statut} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </>
    );
  }

  return (
    <>
      <PageHeader
        title="Tableau de bord global"
        subtitle="Vue d'ensemble des magasins, commandes et stocks"
      />

      {error && <p className="error-text">{error}</p>}

      {dashboard && (
        <>
          <div className="stats-grid">
            <StatCard label="Magasins actifs" value={dashboard.stats.magasinsActifs} />
            <StatCard
              label="Commandes en attente"
              value={dashboard.stats.commandesEnAttente}
              alert={dashboard.stats.commandesEnAttente > 0}
            />
            <StatCard
              label="Alertes stock production"
              value={dashboard.stats.alertesStockProduction}
              alert={dashboard.stats.alertesStockProduction > 0}
            />
            <StatCard
              label="Alertes inventaire magasins"
              value={dashboard.stats.alertesInventaireMagasins}
              alert={dashboard.stats.alertesInventaireMagasins > 0}
            />
          </div>

          <div className="grid-2">
            <section className="panel">
              <h2>Commandes récentes</h2>
              <div className="table-wrap">
                <table>
                  <thead>
                    <tr>
                      <th>Numéro</th>
                      <th>Magasin</th>
                      <th>Statut</th>
                    </tr>
                  </thead>
                  <tbody>
                    {dashboard.commandesRecentes.map((commande) => (
                      <tr key={commande.id}>
                        <td>{commande.numero}</td>
                        <td>{commande.magasin?.nom}</td>
                        <td><StatusBadge statut={commande.statut} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>

            <section className="panel">
              <h2>Alertes</h2>
              <div className="alert-list">
                {dashboard.alertes.inventairesMagasins.slice(0, 5).map((item) => (
                  <div key={item.id} className="alert-item">
                    <strong>{item.produit.nom}</strong>
                    <span>{item.magasin?.nom ?? 'Magasin'} — {item.quantite} restants</span>
                  </div>
                ))}
                {dashboard.alertes.stockProduits.slice(0, 3).map((item) => (
                  <div key={item.id} className="alert-item">
                    <strong>Stock production : {item.produit.nom}</strong>
                    <span>{item.quantite} {item.produit.unite}</span>
                  </div>
                ))}
                {dashboard.alertes.stockMarchandises.slice(0, 3).map((item) => (
                  <div key={item.id} className="alert-item">
                    <strong>Matière : {item.marchandise.nom}</strong>
                    <span>{item.quantite} {item.marchandise.unite}</span>
                  </div>
                ))}
              </div>
            </section>
          </div>
        </>
      )}
    </>
  );
}

