    return <p className="error-text">Aucun magasin associé à ce compte.</p>;
  }

  return (
    <>
      <PageHeader
        title="Inventaire du magasin"
        subtitle={user?.magasin ? `Magasin : ${user.magasin.nom}` : undefined}
      />

      <InventaireMagasinPanel
        magasinId={magasinId}
        magasinNom={user?.magasin?.nom}
      />
    </>
  );
}

