  async function updateItem(
    marchandiseId: string,
    data: { quantite?: number; seuilAlerte?: number },
  ) {
    try {
      const updated = await stockApi.updateMarchandise(marchandiseId, data);
      setStock((items) =>
        items.map((item) => (item.marchandiseId === marchandiseId ? updated : item)),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  return (
    <>
      <PageHeader
        title="Inventaire matières premières"
        subtitle="Stock des matières premières au centre de production"
      />

      {error && <p className="error-text">{error}</p>}

      <div className="grid-2">
        <section className="panel">
          <h2>Inventaire matières premières</h2>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Nom</th>
                  <th>Catégorie</th>
                  <th>Quantité</th>
                  <th>Seuil d'alerte</th>
                  <th>Unité</th>
                  <th>État</th>
                </tr>
              </thead>
              <tbody>
                {stock.map((item) => {
                  const lowStock = item.quantite <= item.seuilAlerte;
                  return (
                    <tr key={item.id} className={lowStock ? 'row-alert' : ''}>
                      <td><strong>{item.marchandise.nom}</strong></td>
                      <td>{item.marchandise.categorie}</td>
                      <td>
                        <input
                          type="number"
                          min="0"
                          step="0.1"
                          value={item.quantite}
                          onChange={(e) =>
                            updateItem(item.marchandiseId, { quantite: Number(e.target.value) })
                          }
                        />
