import { FormEvent, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { commandesApi } from '../lib/api';
import { PageHeader, StatusBadge } from '../components/UI';
import type { Commande, StatutCommande } from '../types';

const nextStatut: Partial<Record<StatutCommande, StatutCommande>> = {
  EN_ATTENTE: 'EN_PREPARATION',
  EN_PREPARATION: 'EXPEDIEE',
  EXPEDIEE: 'LIVREE',
};

const editableStatuts: StatutCommande[] = ['EN_ATTENTE', 'EN_PREPARATION', 'EXPEDIEE'];

export function CommandesPage() {
  const { user } = useAuth();
  const [commandes, setCommandes] = useState<Commande[]>([]);
  const [error, setError] = useState('');
  const [loadingId, setLoadingId] = useState<string | null>(null);
  const [editing, setEditing] = useState<Commande | null>(null);
  const [editLignes, setEditLignes] = useState<{ produitId: string; nom: string; quantite: number }[]>([]);
  const [editNotes, setEditNotes] = useState('');
  const [savingEdit, setSavingEdit] = useState(false);

  const canManage = user?.role === 'PRODUCTION' || user?.role === 'ADMIN';

  useEffect(() => {
    commandesApi
      .list()
      .then(setCommandes)
      .catch((err) => setError(err.message));
  }, []);

  function startEdit(commande: Commande) {
    setEditing(commande);
    setEditLignes(
      commande.lignes.map((ligne) => ({
        produitId: ligne.produitId,
        nom: ligne.produit.nom,
        quantite: ligne.quantite,
      })),
    );
    setEditNotes(commande.notes ?? '');
    setError('');
  }

  function cancelEdit() {
    setEditing(null);
    setEditLignes([]);
    setEditNotes('');
  }

  async function saveEdit(event: FormEvent) {
    event.preventDefault();
    if (!editing) return;

    const lignes = editLignes
      .filter((ligne) => ligne.quantite > 0)
      .map(({ produitId, quantite }) => ({ produitId, quantite }));

    if (lignes.length === 0) {
      setError('Ajoutez au moins un produit avec une quantité');
      return;
    }

    setSavingEdit(true);
    setError('');
    try {
      const updated = await commandesApi.update(editing.id, {
        lignes,
        notes: editNotes || undefined,
      });
      setCommandes((items) => items.map((item) => (item.id === updated.id ? updated : item)));
      cancelEdit();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setSavingEdit(false);
    }
  }

  async function advanceStatut(commande: Commande) {
    const next = nextStatut[commande.statut];
    if (!next) return;

    setLoadingId(commande.id);
    try {
      await commandesApi.updateStatut(commande.id, next);
      if (next === 'LIVREE') {
        setCommandes((items) => items.filter((item) => item.id !== commande.id));
        if (editing?.id === commande.id) cancelEdit();
      } else {
        const updated = await commandesApi.list();
        setCommandes(updated);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setLoadingId(null);
    }
  }

  return (
    <>
      <PageHeader
        title={user?.role === 'MAGASIN' ? 'Mes commandes' : 'Commandes reçues'}
        subtitle={
          user?.role === 'PRODUCTION'
            ? 'Modifiez et traitez les commandes — les commandes livrées disparaissent automatiquement'
            : 'Suivi des commandes en cours (les commandes livrées ne sont plus affichées)'
        }
        action={
          user?.role === 'MAGASIN' ? (
            <Link to="/nouvelle-commande" className="btn btn-primary">
              Nouvelle commande
            </Link>
          ) : undefined
        }
      />

      {error && <p className="error-text">{error}</p>}

      {editing && canManage && (
        <section className="panel form-panel commande-edit-panel">
          <h2>Modifier la commande {editing.numero}</h2>
          <p className="muted">
            Magasin : {editing.magasin?.nom} — Statut : <StatusBadge statut={editing.statut} />
          </p>
          <form onSubmit={saveEdit}>
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>Produit</th>
                    <th>Quantité</th>
                  </tr>
                </thead>
                <tbody>
                  {editLignes.map((ligne, index) => (
                    <tr key={ligne.produitId}>
                      <td>{ligne.nom}</td>
                      <td>
                        <input
                          type="number"
                          min="0"
                          step="1"
                          value={ligne.quantite}
                          onChange={(e) =>
                            setEditLignes((items) =>
                              items.map((item, i) =>
                                i === index ? { ...item, quantite: Number(e.target.value) } : item,
                              ),
                            )
                          }
                        />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <label>
              Notes
              <textarea
                rows={3}
                value={editNotes}
                onChange={(e) => setEditNotes(e.target.value)}
                placeholder="Notes pour la production ou le magasin"
              />
            </label>

            <div className="form-actions">
              <button type="submit" className="btn btn-primary" disabled={savingEdit}>
                {savingEdit ? 'Enregistrement...' : 'Enregistrer'}
              </button>
              <button type="button" className="btn btn-secondary" onClick={cancelEdit}>
                Annuler
              </button>
            </div>
          </form>
        </section>
      )}

      <section className="panel">
        {commandes.length === 0 ? (
          <p className="muted">Aucune commande en cours.</p>
        ) : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Numéro</th>
                  {user?.role !== 'MAGASIN' && <th>Magasin</th>}
                  <th>Date</th>
                  <th>Produits</th>
                  <th>Notes</th>
                  <th>Statut</th>
                  {canManage && <th>Actions</th>}
                </tr>
              </thead>
              <tbody>
                {commandes.map((commande) => (
                  <tr key={commande.id}>
                    <td><strong>{commande.numero}</strong></td>
                    {user?.role !== 'MAGASIN' && <td>{commande.magasin?.nom}</td>}
                    <td>{new Date(commande.createdAt).toLocaleString('fr-FR')}</td>
                    <td>
                      <ul className="inline-list">
                        {commande.lignes.map((ligne) => (
                          <li key={ligne.id}>
                            {ligne.quantite} × {ligne.produit.nom}
                          </li>
                        ))}
                      </ul>
                    </td>
                    <td>{commande.notes || '—'}</td>
                    <td><StatusBadge statut={commande.statut} /></td>
                    {canManage && (
                      <td>
                        <div className="action-group">
                          {editableStatuts.includes(commande.statut) && (
                            <button
                              type="button"
                              className="btn btn-secondary btn-sm"
                              onClick={() => startEdit(commande)}
                            >
                              Modifier
                            </button>
                          )}
                          {nextStatut[commande.statut] && (
                            <button
                              type="button"
                              className="btn btn-primary btn-sm"
                              disabled={loadingId === commande.id}
                              onClick={() => advanceStatut(commande)}
                            >
                              → {nextStatut[commande.statut]}
                            </button>
                          )}
                        </div>
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </>
  );
}

