import { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { commandesApi, produitsApi } from '../lib/api';
import { PageHeader } from '../components/UI';
import type { Produit } from '../types';

export function NouvelleCommandePage() {
  const navigate = useNavigate();
  const [produits, setProduits] = useState<Produit[]>([]);
  const [search, setSearch] = useState('');
  const [quantites, setQuantites] = useState<Record<string, number>>({});
  const [notes, setNotes] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    produitsApi
      .list()
      .then(setProduits)
      .catch((err) => setError(err.message));
  }, []);

  const filteredProduits = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) return produits;
    return produits.filter(
      (p) =>
        p.nom.toLowerCase().includes(query) ||
        p.categorie.toLowerCase().includes(query),
    );
  }, [produits, search]);

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();

    const lignes = Object.entries(quantites)
      .filter(([, quantite]) => quantite > 0)
      .map(([produitId, quantite]) => ({ produitId, quantite }));

    if (lignes.length === 0) {
      setError('Ajoutez au moins un article à la commande');
      return;
    }

    setLoading(true);
    setError('');

    try {
      await commandesApi.create({ lignes, notes: notes || undefined });
      navigate('/commandes');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setLoading(false);
    }
  }

  return (
    <>
      <PageHeader
        title="Nouvelle commande"
        subtitle="Commandez n'importe quel article du catalogue — le stock n'est pas bloquant"
      />

      {error && <p className="error-text">{error}</p>}

      <form onSubmit={handleSubmit} className="panel form-panel">
        <h2>Choisir les articles</h2>

        <label>
          Rechercher un article
          <input
            type="search"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Nom ou catégorie..."
          />
        </label>

        <div className="product-order-grid">
          {filteredProduits.map((produit) => (
            <label key={produit.id} className="product-order-card">
              <div>
                <strong>{produit.nom}</strong>
                <span>{produit.categorie} — {produit.prix.toFixed(2)} €</span>
              </div>
              <input
                type="number"
                min="0"
                step="1"
                placeholder="0"
                value={quantites[produit.id] ?? ''}
                onChange={(e) =>
                  setQuantites((prev) => ({
                    ...prev,
                    [produit.id]: Number(e.target.value) || 0,
                  }))
                }
              />
            </label>
          ))}
        </div>

        {filteredProduits.length === 0 && (
          <p className="muted">Aucun article ne correspond à votre recherche.</p>
        )}

        <label>
          Annotations pour la production
          <textarea
            rows={3}
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            placeholder="Ex : livraison demain matin à 6h, produit en rupture accepté..."
          />
        </label>

        <button type="submit" className="btn btn-primary" disabled={loading}>
          {loading ? 'Envoi...' : 'Envoyer la commande'}
        </button>
      </form>
    </>
  );
}

