router.patch('/:id', async (req, res) => {
  const { lignes, notes } = req.body;

  const existing = await prisma.commande.findUnique({
    where: { id: req.params.id },
    include: { lignes: true },
  });

  if (!existing) {
    return res.status(404).json({ error: 'Commande introuvable' });
  }

  if (['LIVREE', 'ANNULEE'].includes(existing.statut)) {
    return res.status(400).json({ error: 'Cette commande ne peut plus être modifiée' });
  }

  if (req.user.role === 'MAGASIN') {
    if (req.user.magasinId !== existing.magasinId) {
      return res.status(403).json({ error: 'Accès non autorisé' });
    }

    if (lignes !== undefined) {
      return res.status(403).json({ error: 'Vous ne pouvez modifier que les annotations' });
    }

    const commande = await prisma.commande.update({
      where: { id: existing.id },
      data: { notes },
      include: {
        magasin: true,
        lignes: { include: { produit: true } },
      },
    });

    return res.json(commande);
  }

  if (!['PRODUCTION', 'ADMIN'].includes(req.user.role)) {
    return res.status(403).json({ error: 'Accès non autorisé' });
  }

  if (lignes !== undefined) {
    if (!lignes.length) {
      return res.status(400).json({ error: 'Au moins une ligne de commande est requise' });
    }

    const commande = await prisma.$transaction(async (tx) => {
      await tx.ligneCommande.deleteMany({ where: { commandeId: existing.id } });

      return tx.commande.update({
        where: { id: existing.id },
        data: {
          ...(notes !== undefined && { notes }),
          lignes: {
            create: lignes.map((ligne) => ({
              produitId: ligne.produitId,
              quantite: ligne.quantite,
            })),
          },
        },
        include: {
          magasin: true,
          lignes: { include: { produit: true } },
        },
      });
    });

    return res.json(commande);
  }

  if (notes === undefined) {
    return res.status(400).json({ error: 'Aucune modification fournie' });
  }

  const commande = await prisma.commande.update({
    where: { id: existing.id },
    data: { notes },
    include: {
      magasin: true,
      lignes: { include: { produit: true } },
    },
  });

  res.json(commande);
});

