import { inventaireApi } from '../lib/api';
import { AddInventaireForm } from './AddForms';
import type { InventaireMagasin } from '../types';

interface InventaireMagasinPanelProps {
  magasinId: string;
  magasinNom?: string;
  showAddForm?: boolean;
  allowRemove?: boolean;
  onSync?: () => Promise<void>;
  syncing?: boolean;
}

export function InventaireMagasinPanel({
  magasinId,
  magasinNom,
  showAddForm = true,
  allowRemove = true,
  onSync,
  syncing = false,
}: InventaireMagasinPanelProps) {
  const [inventaires, setInventaires] = useState<InventaireMagasin[]>([]);
  const [error, setError] = useState('');
  const [savingId, setSavingId] = useState<string | null>(null);

  async function load() {
    setInventaires(await inventaireApi.list(magasinId));
  }

  useEffect(() => {
    load().catch((err) => setError(err.message));
  }, [magasinId]);

  async function updateItem(
    produitId: string,
    data: { quantite?: number; seuilAlerte?: number },
  ) {
    setSavingId(produitId);
    try {
      const updated = await inventaireApi.update(produitId, { magasinId, ...data });
      setInventaires((items) =>
        items.map((item) => (item.produitId === produitId ? updated : item)),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setSavingId(null);
    }
  }

  async function adjustQuantite(produitId: string, delta: number) {
    const item = inventaires.find((i) => i.produitId === produitId);
    if (!item) return;
    await updateItem(produitId, { quantite: Math.max(0, item.quantite + delta) });
  }

  async function removeItem(produitId: string) {
    if (!window.confirm('Retirer cet article de l\'inventaire du magasin ?')) return;

    setSavingId(produitId);
    setError('');
    try {
      await inventaireApi.remove(produitId, magasinId);
      setInventaires((items) => items.filter((item) => item.produitId !== produitId));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setSavingId(null);
    }
  }

  function handleAdded(item: InventaireMagasin) {
    setInventaires((items) =>
      [...items, item].sort((a, b) => a.produit.nom.localeCompare(b.produit.nom)),
    );
  }

  return (
    <>
      {error && <p className="error-text">{error}</p>}

      {magasinNom && (
        <p className="muted panel-intro">
          Gérez librement le stock du magasin <strong>{magasinNom}</strong> : ajoutez ou retirez
          des articles et ajustez les quantités.
        </p>
      )}

      {onSync && (
        <div className="panel-actions">
          <button
            type="button"
            className="btn btn-secondary btn-sm"
            disabled={syncing}
            onClick={() => onSync().then(() => load()).catch((err) => setError(err.message))}
          >
            {syncing ? 'Synchronisation...' : 'Synchroniser les produits manquants'}
          </button>
        </div>
      )}

      <div className={showAddForm ? 'grid-2' : ''}>
        <section className="panel">
          <h2>Articles en boutique</h2>
          {inventaires.length === 0 ? (
            <p className="muted">Aucun article dans l'inventaire. Ajoutez-en depuis le panneau à droite.</p>
          ) : (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>Produit</th>
                    <th>Catégorie</th>
                    <th>Quantité</th>
                    <th>Seuil d'alerte</th>
                    <th>État</th>
                    {allowRemove && <th>Actions</th>}
                  </tr>
                </thead>
                <tbody>
                  {inventaires.map((item) => {
                    const lowStock = item.quantite <= item.seuilAlerte;
                    return (
                      <tr key={item.id} className={lowStock ? 'row-alert' : ''}>
                        <td>
                          <strong>{item.produit.nom}</strong>
                          <small>{item.produit.unite}</small>
                        </td>
                        <td>{item.produit.categorie}</td>
                        <td>
                          <div className="qty-controls">
                            <button
                              type="button"
                              className="btn btn-secondary btn-sm"
                              disabled={savingId === item.produitId}
                              onClick={() => adjustQuantite(item.produitId, -1)}
                            >
                              −
                            </button>
                            <input
                              type="number"
                              min="0"
                              step="1"
                              value={item.quantite}
                              onChange={(e) =>
                                updateItem(item.produitId, { quantite: Number(e.target.value) })
                              }
                              disabled={savingId === item.produitId}
                            />
                            <button
                              type="button"
                              className="btn btn-secondary btn-sm"
                              disabled={savingId === item.produitId}
                              onClick={() => adjustQuantite(item.produitId, 1)}
                            >
                              +
                            </button>
                          </div>
                        </td>
                        <td>
                          <input
                            type="number"
                            min="0"
                            step="1"
                            value={item.seuilAlerte}
                            onChange={(e) =>
                              updateItem(item.produitId, { seuilAlerte: Number(e.target.value) })
                            }
                            disabled={savingId === item.produitId}
                          />
                        </td>
                        <td>{lowStock ? '⚠️ Stock bas' : 'OK'}</td>
                        {allowRemove && (
                          <td>
                            <button
                              type="button"
                              className="btn btn-secondary btn-sm"
                              disabled={savingId === item.produitId}
                              onClick={() => removeItem(item.produitId)}
                            >
                              Retirer
                            </button>
                          </td>
                        )}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </section>

        {showAddForm && (
          <section className="panel form-panel">
            <h2>Ajouter un article</h2>
            <AddInventaireForm
              magasinId={magasinId}
              existingProduitIds={inventaires.map((i) => i.produitId)}
              onAdded={handleAdded}
            />
          </section>
        )}
      </div>
    </>
  );
}

