export function AddInventaireForm({
  magasinId,
  existingProduitIds,
  onAdded,
}: {
  magasinId: string;
  existingProduitIds: string[];
  onAdded?: (item: InventaireMagasin) => void;
}) {
  const [produits, setProduits] = useState<Produit[]>([]);
  const [search, setSearch] = useState('');
  const [produitId, setProduitId] = useState('');
  const [quantite, setQuantite] = useState(0);
  const [seuilAlerte, setSeuilAlerte] = useState(5);
  const [error, setError] = useState('');

  const available = produits.filter((p) => !existingProduitIds.includes(p.id));
  const filtered = available.filter((p) => {
    const query = search.trim().toLowerCase();
    if (!query) return true;
    return p.nom.toLowerCase().includes(query) || p.categorie.toLowerCase().includes(query);
  });

  useEffect(() => {
    produitsApi
      .list()
      .then(setProduits)
      .catch((err) => setError(err.message));
  }, []);

  useEffect(() => {
    if (filtered.length > 0 && !filtered.some((p) => p.id === produitId)) {
      setProduitId(filtered[0].id);
    }
  }, [filtered, produitId]);

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    if (!produitId) {
      setError('Choisissez un article à ajouter');
      return;
    }
    setError('');
    try {
      const item = await inventaireApi.update(produitId, {
        magasinId,
        quantite,
        seuilAlerte,
      });
      setQuantite(0);
      setSeuilAlerte(5);
      setSearch('');
      onAdded?.(item);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  if (available.length === 0) {
    return <p className="muted">Tous les articles du catalogue sont déjà dans l'inventaire.</p>;
  }

  return (
    <form onSubmit={handleSubmit} className="add-form">
      {error && <p className="error-text">{error}</p>}
      <label>
        Rechercher un article
        <input
          type="search"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Nom ou catégorie..."
        />
      </label>
      <label>
        Article
        <select value={produitId} onChange={(e) => setProduitId(e.target.value)} required>
          {filtered.map((p) => (
            <option key={p.id} value={p.id}>
              {p.nom} ({p.categorie})
            </option>
          ))}
        </select>
      </label>
      {filtered.length === 0 && <p className="muted">Aucun article ne correspond.</p>}
      <label>
        Quantité initiale
        <input
          type="number"
          min="0"
          step="1"
          value={quantite}
          onChange={(e) => setQuantite(Number(e.target.value))}
        />
      </label>
      <label>
        Seuil d'alerte
        <input
          type="number"
          min="0"
          step="1"
          value={seuilAlerte}
          onChange={(e) => setSeuilAlerte(Number(e.target.value))}
        />
      </label>
      <button type="submit" className="btn btn-primary" disabled={filtered.length === 0}>
        Ajouter au stock
      </button>
    </form>
  );
}

