import { useEffect, useMemo, useRef, useState } from 'react';
import { inventaireApi } from '../lib/api';
import { AddInventaireForm } from './AddForms';
import type { InventaireMagasin } from '../types';

interface InventaireMagasinPanelProps {
  magasinId: string;
  magasinNom?: string;
  showAddForm?: boolean;
  allowRemove?: boolean;
  onSync?: () => Promise<void>;
  syncing?: boolean;
}

function stockLevel(quantite: number, seuil: number): number {
  if (seuil <= 0) return quantite > 0 ? 100 : 0;
  return Math.min(100, Math.round((quantite / (seuil * 2)) * 100));
}

export function InventaireMagasinPanel({
  magasinId,
  magasinNom,
  showAddForm = true,
  allowRemove = true,
  onSync,
  syncing = false,
}: InventaireMagasinPanelProps) {
  const [inventaires, setInventaires] = useState<InventaireMagasin[]>([]);
  const [search, setSearch] = useState('');
  const [categorie, setCategorie] = useState('');
  const [alertOnly, setAlertOnly] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [error, setError] = useState('');
  const [toast, setToast] = useState('');
  const [savingId, setSavingId] = useState<string | null>(null);
  const [localQty, setLocalQty] = useState<Record<string, string>>({});
  const toastTimer = useRef<ReturnType<typeof setTimeout>>();

  async function load() {
    const items = await inventaireApi.list(magasinId);
    setInventaires(items);
    setLocalQty(Object.fromEntries(items.map((i) => [i.produitId, String(i.quantite)])));
  }

  useEffect(() => {
    load().catch((err) => setError(err.message));
  }, [magasinId]);

  useEffect(() => () => {
    if (toastTimer.current) clearTimeout(toastTimer.current);
  }, []);

  function notify(message: string) {
    setToast(message);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(''), 2500);
  }

  const categories = useMemo(
    () => [...new Set(inventaires.map((i) => i.produit.categorie))].sort(),
    [inventaires],
  );

  const stats = useMemo(() => {
    const alertes = inventaires.filter((i) => i.quantite <= i.seuilAlerte).length;
    return { total: inventaires.length, alertes, categories: categories.length };
  }, [inventaires, categories]);

  const filtered = useMemo(() => {
    const query = search.trim().toLowerCase();
    return inventaires.filter((item) => {
      if (alertOnly && item.quantite > item.seuilAlerte) return false;
      if (categorie && item.produit.categorie !== categorie) return false;
      if (!query) return true;
      return (
        item.produit.nom.toLowerCase().includes(query) ||
        item.produit.categorie.toLowerCase().includes(query)
      );
    });
  }, [inventaires, search, categorie, alertOnly]);

  async function updateItem(
    produitId: string,
    data: { quantite?: number; seuilAlerte?: number },
  ) {
    setSavingId(produitId);
    setError('');
    try {
      const updated = await inventaireApi.update(produitId, { magasinId, ...data });
      setInventaires((items) =>
        items.map((item) => (item.produitId === produitId ? updated : item)),
      );
      if (data.quantite != null) {
        setLocalQty((prev) => ({ ...prev, [produitId]: String(updated.quantite) }));
      }
      notify('Stock mis à jour');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setSavingId(null);
    }
  }

  async function adjustQuantite(produitId: string, delta: number) {
    const item = inventaires.find((i) => i.produitId === produitId);
    if (!item) return;
    const next = Math.max(0, item.quantite + delta);
    setLocalQty((prev) => ({ ...prev, [produitId]: String(next) }));
    await updateItem(produitId, { quantite: next });
  }

  function commitQuantite(produitId: string) {
    const raw = localQty[produitId];
    const value = Math.max(0, Number(raw) || 0);
    const item = inventaires.find((i) => i.produitId === produitId);
    if (!item || item.quantite === value) return;
    updateItem(produitId, { quantite: value });
  }

  async function removeItem(produitId: string) {
    if (!window.confirm('Retirer cet article de l\'inventaire du magasin ?')) return;

    setSavingId(produitId);
    setError('');
    try {
      await inventaireApi.remove(produitId, magasinId);
      setInventaires((items) => items.filter((item) => item.produitId !== produitId));
      notify('Article retiré');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setSavingId(null);
    }
  }

  function handleAdded(item: InventaireMagasin) {
    setInventaires((items) =>
      [...items, item].sort((a, b) => a.produit.nom.localeCompare(b.produit.nom)),
    );
    setLocalQty((prev) => ({ ...prev, [item.produitId]: String(item.quantite) }));
    setShowAddModal(false);
    notify(`${item.produit.nom} ajouté`);
  }

  return (
    <>
      {toast && <p className="toast-banner">{toast}</p>}
      {error && <p className="error-text">{error}</p>}

      <div className="stats-grid inventaire-stats">
        <div className="stat-card">
          <span className="stat-label">Articles en stock</span>
          <span className="stat-value">{stats.total}</span>
        </div>
        <div className={`stat-card ${stats.alertes > 0 ? 'stat-card-alert' : ''}`}>
          <span className="stat-label">Stock bas</span>
          <span className="stat-value">{stats.alertes}</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Catégories</span>
          <span className="stat-value">{stats.categories}</span>
        </div>
        {magasinNom && (
          <div className="stat-card stat-card-info">
            <span className="stat-label">Magasin</span>
            <span className="stat-value stat-value-sm">{magasinNom}</span>
          </div>
        )}
      </div>

      <section className="panel inventaire-toolbar">
        <div className="inventaire-toolbar-row">
          <label className="inventaire-search">
            <span className="sr-only">Rechercher</span>
            <input
              type="search"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="🔍  Rechercher un article..."
            />
          </label>

          {showAddForm && (
            <button
              type="button"
              className="btn btn-primary"
              onClick={() => setShowAddModal(true)}
            >
              + Ajouter
            </button>
          )}

          {onSync && (
            <button
              type="button"
              className="btn btn-secondary btn-sm"
              disabled={syncing}
              onClick={() => onSync().then(() => load()).catch((err) => setError(err.message))}
            >
              {syncing ? 'Sync...' : 'Synchroniser'}
            </button>
          )}
        </div>

        <div className="inventaire-filters">
          <button
            type="button"
            className={`filter-chip ${!categorie && !alertOnly ? 'active' : ''}`}
            onClick={() => { setCategorie(''); setAlertOnly(false); }}
          >
            Tous
          </button>
          <button
            type="button"
            className={`filter-chip ${alertOnly ? 'active' : ''}`}
            onClick={() => setAlertOnly((v) => !v)}
          >
            ⚠ Stock bas {stats.alertes > 0 && `(${stats.alertes})`}
          </button>
          {categories.map((cat) => (
            <button
              key={cat}
              type="button"
              className={`filter-chip ${categorie === cat ? 'active' : ''}`}
              onClick={() => setCategorie((c) => (c === cat ? '' : cat))}
            >
              {cat}
            </button>
          ))}
        </div>
      </section>

      <section className="panel">
        {filtered.length === 0 ? (
          <div className="inventaire-empty">
            <p className="muted">
              {inventaires.length === 0
                ? 'Aucun article dans l\'inventaire.'
                : 'Aucun article ne correspond à votre recherche.'}
            </p>
            {showAddForm && inventaires.length === 0 && (
              <button type="button" className="btn btn-primary" onClick={() => setShowAddModal(true)}>
                Ajouter le premier article
              </button>
            )}
          </div>
        ) : (
          <div className="inventaire-grid">
            {filtered.map((item) => {
              const lowStock = item.quantite <= item.seuilAlerte;
              const level = stockLevel(item.quantite, item.seuilAlerte);
              const isSaving = savingId === item.produitId;
              const isExpanded = expandedId === item.id;

              return (
                <article
                  key={item.id}
                  className={`inventaire-card ${lowStock ? 'inventaire-card-alert' : ''} ${isSaving ? 'inventaire-card-saving' : ''}`}
                >
                  <div className="inventaire-card-head">
                    <div>
                      <h3>{item.produit.nom}</h3>
                      <span className="category-badge">{item.produit.categorie}</span>
                    </div>
                    <span className={`stock-badge ${lowStock ? 'stock-badge-alert' : 'stock-badge-ok'}`}>
                      {lowStock ? 'Stock bas' : 'OK'}
                    </span>
                  </div>

                  <div className="stock-bar" aria-hidden>
                    <div
                      className={`stock-bar-fill ${lowStock ? 'stock-bar-fill-alert' : ''}`}
                      style={{ width: `${level}%` }}
                    />
                  </div>

                  <div className="inventaire-card-qty">
                    <button
                      type="button"
                      className="qty-btn qty-btn-minus"
                      disabled={isSaving || item.quantite <= 0}
                      onClick={() => adjustQuantite(item.produitId, -1)}
                      aria-label="Retirer 1"
                    >
                      −
                    </button>
                    <input
                      type="number"
                      min="0"
                      step="1"
                      className="qty-input"
                      value={localQty[item.produitId] ?? item.quantite}
                      disabled={isSaving}
                      onChange={(e) =>
                        setLocalQty((prev) => ({ ...prev, [item.produitId]: e.target.value }))
                      }
                      onBlur={() => commitQuantite(item.produitId)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.currentTarget.blur();
                        }
                      }}
                    />
                    <button
                      type="button"
                      className="qty-btn qty-btn-plus"
                      disabled={isSaving}
                      onClick={() => adjustQuantite(item.produitId, 1)}
                      aria-label="Ajouter 1"
                    >
                      +
                    </button>
                    <span className="qty-unit">{item.produit.unite}</span>
                  </div>

                  <div className="inventaire-card-foot">
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      onClick={() => setExpandedId(isExpanded ? null : item.id)}
                    >
                      {isExpanded ? 'Moins d\'options' : 'Options'}
                    </button>
                    {isSaving && <span className="muted saving-label">Enregistrement...</span>}
                  </div>

                  {isExpanded && (
                    <div className="inventaire-card-options">
                      <label>
                        Seuil d'alerte
                        <input
                          type="number"
                          min="0"
                          step="1"
                          defaultValue={item.seuilAlerte}
                          disabled={isSaving}
                          onBlur={(e) => {
                            const value = Math.max(0, Number(e.target.value) || 0);
                            if (value !== item.seuilAlerte) {
                              updateItem(item.produitId, { seuilAlerte: value });
                            }
                          }}
                        />
                      </label>
                      {allowRemove && (
                        <button
                          type="button"
                          className="btn btn-secondary btn-sm inventaire-remove-btn"
                          disabled={isSaving}
                          onClick={() => removeItem(item.produitId)}
                        >
                          Retirer de l'inventaire
                        </button>
                      )}
                    </div>
                  )}
                </article>
              );
            })}
          </div>
        )}
      </section>

      {showAddModal && (
        <div className="modal-overlay" onClick={() => setShowAddModal(false)}>
          <div
            className="modal-panel"
            role="dialog"
            aria-labelledby="add-inventaire-title"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="modal-header">
              <h2 id="add-inventaire-title">Ajouter un article</h2>
              <button
                type="button"
                className="modal-close"
                onClick={() => setShowAddModal(false)}
                aria-label="Fermer"
              >
                ×
              </button>
            </div>
            <AddInventaireForm
              magasinId={magasinId}
              existingProduitIds={inventaires.map((i) => i.produitId)}
              onAdded={handleAdded}
            />
          </div>
        </div>
      )}
    </>
  );
}

