import { ReactNode, useEffect, useMemo, useRef, useState } from 'react';

export interface InventaireGridItem {
  id: string;
  itemKey: string;
  nom: string;
  categorie: string;
  quantite: number;
  seuilAlerte: number;
  unite: string;
}

interface InventaireGridPanelProps {
  items: InventaireGridItem[];
  contextLabel?: string;
  intro?: string;
  step?: number;
  savingKey?: string | null;
  showAdd?: boolean;
  addLabel?: string;
  addModalTitle?: string;
  addForm?: ReactNode;
  emptyLabel?: string;
  toolbarExtra?: ReactNode;
  allowRemove?: boolean;
  onUpdate: (itemKey: string, data: { quantite?: number; seuilAlerte?: number }) => Promise<void>;
  onRemove?: (itemKey: string) => Promise<void>;
}

function stockLevel(quantite: number, seuil: number): number {
  if (seuil <= 0) return quantite > 0 ? 100 : 0;
  return Math.min(100, Math.round((quantite / (seuil * 2)) * 100));
}

function formatQty(value: number, step: number): string {
  if (step >= 1) return String(Math.round(value));
  return String(Number(value.toFixed(2)));
}

export function InventaireGridPanel({
  items,
  contextLabel,
  intro,
  step = 1,
  savingKey = null,
  showAdd = false,
  addLabel = '+ Ajouter',
  addModalTitle = 'Ajouter',
  addForm,
  emptyLabel = 'Aucun article dans l\'inventaire.',
  toolbarExtra,
  allowRemove = false,
  onUpdate,
  onRemove,
}: InventaireGridPanelProps) {
  const [search, setSearch] = useState('');
  const [categorie, setCategorie] = useState('');
  const [alertOnly, setAlertOnly] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [toast, setToast] = useState('');
  const [localQty, setLocalQty] = useState<Record<string, string>>({});
  const toastTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => {
    setLocalQty(Object.fromEntries(items.map((i) => [i.itemKey, formatQty(i.quantite, step)])));
  }, [items, step]);

  useEffect(() => () => {
    if (toastTimer.current) clearTimeout(toastTimer.current);
  }, []);

  function notify(message: string) {
    setToast(message);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(''), 2500);
  }

  const categories = useMemo(
    () => [...new Set(items.map((i) => i.categorie))].sort(),
    [items],
  );

  const stats = useMemo(() => {
    const alertes = items.filter((i) => i.quantite <= i.seuilAlerte).length;
    return { total: items.length, alertes, categories: categories.length };
  }, [items, categories]);

  const filtered = useMemo(() => {
    const query = search.trim().toLowerCase();
    return items.filter((item) => {
      if (alertOnly && item.quantite > item.seuilAlerte) return false;
      if (categorie && item.categorie !== categorie) return false;
      if (!query) return true;
      return (
        item.nom.toLowerCase().includes(query) ||
        item.categorie.toLowerCase().includes(query)
      );
    });
  }, [items, search, categorie, alertOnly]);

  async function adjustQuantite(itemKey: string, delta: number) {
    const item = items.find((i) => i.itemKey === itemKey);
    if (!item) return;
    const next = Math.max(0, Number((item.quantite + delta).toFixed(step < 1 ? 2 : 0)));
    setLocalQty((prev) => ({ ...prev, [itemKey]: formatQty(next, step) }));
    await onUpdate(itemKey, { quantite: next });
    notify('Stock mis à jour');
  }

  function commitQuantite(itemKey: string) {
    const raw = localQty[itemKey];
    const value = Math.max(0, Number(raw) || 0);
    const item = items.find((i) => i.itemKey === itemKey);
    if (!item || item.quantite === value) return;
    onUpdate(itemKey, { quantite: value }).then(() => notify('Stock mis à jour'));
  }

  async function handleRemove(itemKey: string) {
    if (!onRemove) return;
    if (!window.confirm('Retirer cet article de l\'inventaire ?')) return;
    await onRemove(itemKey);
    notify('Article retiré');
  }

  return (
    <>
      {toast && <p className="toast-banner">{toast}</p>}

      {intro && <p className="muted panel-intro">{intro}</p>}

      <div className="stats-grid inventaire-stats">
        <div className="stat-card">
          <span className="stat-label">Articles en stock</span>
          <span className="stat-value">{stats.total}</span>
        </div>
        <div className={`stat-card ${stats.alertes > 0 ? 'stat-card-alert' : ''}`}>
          <span className="stat-label">Stock bas</span>
          <span className="stat-value">{stats.alertes}</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Catégories</span>
          <span className="stat-value">{stats.categories}</span>
        </div>
        {contextLabel && (
          <div className="stat-card stat-card-info">
            <span className="stat-label">Contexte</span>
            <span className="stat-value stat-value-sm">{contextLabel}</span>
          </div>
        )}
      </div>

      <section className="panel inventaire-toolbar">
        <div className="inventaire-toolbar-row">
          <label className="inventaire-search">
            <span className="sr-only">Rechercher</span>
            <input
              type="search"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="🔍  Rechercher un article..."
            />
          </label>

          {showAdd && addForm && (
            <button type="button" className="btn btn-primary" onClick={() => setShowAddModal(true)}>
              {addLabel}
            </button>
          )}

          {toolbarExtra}
        </div>

        <div className="inventaire-filters">
          <button
            type="button"
            className={`filter-chip ${!categorie && !alertOnly ? 'active' : ''}`}
            onClick={() => { setCategorie(''); setAlertOnly(false); }}
          >
            Tous
          </button>
          <button
            type="button"
            className={`filter-chip ${alertOnly ? 'active' : ''}`}
            onClick={() => setAlertOnly((v) => !v)}
          >
            ⚠ Stock bas {stats.alertes > 0 && `(${stats.alertes})`}
          </button>
          {categories.map((cat) => (
            <button
              key={cat}
              type="button"
              className={`filter-chip ${categorie === cat ? 'active' : ''}`}
              onClick={() => setCategorie((c) => (c === cat ? '' : cat))}
            >
              {cat}
            </button>
          ))}
        </div>
      </section>

      <section className="panel">
        {filtered.length === 0 ? (
          <div className="inventaire-empty">
            <p className="muted">
              {items.length === 0 ? emptyLabel : 'Aucun article ne correspond à votre recherche.'}
            </p>
            {showAdd && addForm && items.length === 0 && (
              <button type="button" className="btn btn-primary" onClick={() => setShowAddModal(true)}>
                Ajouter le premier article
              </button>
            )}
          </div>
        ) : (
          <div className="inventaire-grid">
            {filtered.map((item) => {
              const lowStock = item.quantite <= item.seuilAlerte;
              const level = stockLevel(item.quantite, item.seuilAlerte);
              const isSaving = savingKey === item.itemKey;
              const isExpanded = expandedId === item.id;

              return (
                <article
                  key={item.id}
                  className={`inventaire-card ${lowStock ? 'inventaire-card-alert' : ''} ${isSaving ? 'inventaire-card-saving' : ''}`}
                >
                  <div className="inventaire-card-head">
                    <div>
                      <h3>{item.nom}</h3>
                      <span className="category-badge">{item.categorie}</span>
                    </div>
                    <span className={`stock-badge ${lowStock ? 'stock-badge-alert' : 'stock-badge-ok'}`}>
                      {lowStock ? 'Stock bas' : 'OK'}
                    </span>
                  </div>

                  <div className="stock-bar" aria-hidden>
                    <div
                      className={`stock-bar-fill ${lowStock ? 'stock-bar-fill-alert' : ''}`}
                      style={{ width: `${level}%` }}
                    />
                  </div>

                  <div className="inventaire-card-qty">
                    <button
                      type="button"
                      className="qty-btn qty-btn-minus"
                      disabled={isSaving || item.quantite <= 0}
                      onClick={() => adjustQuantite(item.itemKey, -step)}
                      aria-label="Retirer"
                    >
                      −
                    </button>
                    <input
                      type="number"
                      min="0"
                      step={step}
                      className="qty-input"
                      value={localQty[item.itemKey] ?? formatQty(item.quantite, step)}
                      disabled={isSaving}
                      onChange={(e) =>
                        setLocalQty((prev) => ({ ...prev, [item.itemKey]: e.target.value }))
                      }
                      onBlur={() => commitQuantite(item.itemKey)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') e.currentTarget.blur();
                      }}
                    />
                    <button
                      type="button"
                      className="qty-btn qty-btn-plus"
                      disabled={isSaving}
                      onClick={() => adjustQuantite(item.itemKey, step)}
                      aria-label="Ajouter"
                    >
                      +
                    </button>
                    <span className="qty-unit">{item.unite}</span>
                  </div>

                  <div className="inventaire-card-foot">
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      onClick={() => setExpandedId(isExpanded ? null : item.id)}
                    >
                      {isExpanded ? 'Moins d\'options' : 'Options'}
                    </button>
                    {isSaving && <span className="muted saving-label">Enregistrement...</span>}
                  </div>

                  {isExpanded && (
                    <div className="inventaire-card-options">
                      <label>
                        Seuil d'alerte
                        <input
                          type="number"
                          min="0"
                          step={step}
                          defaultValue={item.seuilAlerte}
                          disabled={isSaving}
                          onBlur={(e) => {
                            const value = Math.max(0, Number(e.target.value) || 0);
                            if (value !== item.seuilAlerte) {
                              onUpdate(item.itemKey, { seuilAlerte: value }).then(() =>
                                notify('Seuil mis à jour'),
                              );
                            }
                          }}
                        />
                      </label>
                      {allowRemove && onRemove && (
                        <button
                          type="button"
                          className="btn btn-secondary btn-sm inventaire-remove-btn"
                          disabled={isSaving}
                          onClick={() => handleRemove(item.itemKey)}
                        >
                          Retirer de l'inventaire
                        </button>
                      )}
                    </div>
                  )}
                </article>
              );
            })}
          </div>
        )}
      </section>

      {showAddModal && addForm && (
        <div className="modal-overlay" onClick={() => setShowAddModal(false)}>
          <div
            className="modal-panel"
            role="dialog"
            aria-labelledby="inventaire-add-title"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="modal-header">
              <h2 id="inventaire-add-title">{addModalTitle}</h2>
              <button
                type="button"
                className="modal-close"
                onClick={() => setShowAddModal(false)}
                aria-label="Fermer"
              >
                ×
              </button>
            </div>
            {addForm}
          </div>
        </div>
      )}
    </>
  );
}

export function useInventaireToast() {
  const [toast, setToast] = useState('');
  const toastTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => () => {
    if (toastTimer.current) clearTimeout(toastTimer.current);
  }, []);

  function notify(message: string) {
    setToast(message);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(''), 2500);
  }

  return { toast, notify };
}

import { useEffect, useMemo, useState } from 'react';
import { inventaireApi } from '../lib/api';
import { AddInventaireForm } from './AddForms';
import { InventaireGridPanel, type InventaireGridItem } from './InventaireGridPanel';
import type { InventaireMagasin } from '../types';

interface InventaireMagasinPanelProps {
  magasinId: string;
  magasinNom?: string;
  showAddForm?: boolean;
  allowRemove?: boolean;
  onSync?: () => Promise<void>;
  syncing?: boolean;
}

function toGridItem(item: InventaireMagasin): InventaireGridItem {
  return {
    id: item.id,
    itemKey: item.produitId,
    nom: item.produit.nom,
    categorie: item.produit.categorie,
    quantite: item.quantite,
    seuilAlerte: item.seuilAlerte,
    unite: item.produit.unite,
  };
}

export function InventaireMagasinPanel({
  magasinId,
  magasinNom,
  showAddForm = true,
  allowRemove = true,
  onSync,
  syncing = false,
}: InventaireMagasinPanelProps) {
  const [inventaires, setInventaires] = useState<InventaireMagasin[]>([]);
  const [error, setError] = useState('');
  const [savingId, setSavingId] = useState<string | null>(null);

  async function load() {
    setInventaires(await inventaireApi.list(magasinId));
  }

  useEffect(() => {
    load().catch((err) => setError(err.message));
  }, [magasinId]);

  const gridItems = useMemo(() => inventaires.map(toGridItem), [inventaires]);

  async function updateItem(
    produitId: string,
    data: { quantite?: number; seuilAlerte?: number },
  ) {
    setSavingId(produitId);
    setError('');
    try {
      const updated = await inventaireApi.update(produitId, { magasinId, ...data });
      setInventaires((items) =>
        items.map((item) => (item.produitId === produitId ? updated : item)),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
      throw err;
    } finally {
      setSavingId(null);
    }
  }

  async function removeItem(produitId: string) {
    setSavingId(produitId);
    setError('');
    try {
      await inventaireApi.remove(produitId, magasinId);
      setInventaires((items) => items.filter((item) => item.produitId !== produitId));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
      throw err;
    } finally {
      setSavingId(null);
    }
  }

  function handleAdded(item: InventaireMagasin, close: () => void) {
    setInventaires((items) =>
      [...items, item].sort((a, b) => a.produit.nom.localeCompare(b.produit.nom)),
    );
    close();
  }

  return (
    <>
      {error && <p className="error-text">{error}</p>}

      <InventaireGridPanel
        items={gridItems}
        contextLabel={magasinNom}
        intro={
          magasinNom
            ? `Gérez librement le stock du magasin ${magasinNom} : recherchez, filtrez et ajustez en un clic.`
            : undefined
        }
        savingKey={savingId}
        showAdd={showAddForm}
        addLabel="+ Ajouter"
        addModalTitle="Ajouter un article"
        allowRemove={allowRemove}
        onUpdate={updateItem}
        onRemove={allowRemove ? removeItem : undefined}
        addForm={
          showAddForm
            ? (close) => (
                <AddInventaireForm
                  magasinId={magasinId}
                  existingProduitIds={inventaires.map((i) => i.produitId)}
                  onAdded={(item) => handleAdded(item, close)}
                />
              )
            : undefined
        }
        toolbarExtra={
          onSync ? (
            <button
              type="button"
              className="btn btn-secondary btn-sm"
              disabled={syncing}
              onClick={() => onSync().then(() => load()).catch((err) => setError(err.message))}
            >
              {syncing ? 'Sync...' : 'Synchroniser'}
            </button>
          ) : undefined
        }
      />
    </>
  );
}

