                </p>
                <div className="magasin-share-grid">
                  {magasins.map((magasin) => (
                    <label key={magasin.id} className="magasin-share-card">
                      <input
                        type="checkbox"
                        checked={form.magasinIds.includes(magasin.id)}
                        onChange={() => toggleMagasin(magasin.id)}
                      />
                      <span>
