      recette.allergenes.some((a) => a.toLowerCase().includes(q))
    );
  }
  return (
    recette.nom.toLowerCase().includes(q) ||
    (recette.description?.toLowerCase().includes(q) ?? false) ||
    recette.allergenes.some((a) => a.toLowerCase().includes(q)) ||
    (recette.ingredients?.some((i) => i.nom.toLowerCase().includes(q)) ?? false)
  );
}

