const statutActions: Partial<Record<StatutCommande, string>> = {
  EN_PREPARATION: 'Mettre en préparation',
  EXPEDIEE: 'Marquer comme expédiée',
  LIVREE: 'Confirmer la livraison',
};

export function statutActionLabel(next: StatutCommande): string {
  return statutActions[next] ?? `Passer à : ${statutLabels[next]}`;
}

export const workflowSteps: { key: StatutCommande; label: string }[] = [
  { key: 'EN_ATTENTE', label: 'Reçue' },
  { key: 'EN_PREPARATION', label: 'En préparation' },
  { key: 'EXPEDIEE', label: 'Expédiée' },
  { key: 'LIVREE', label: 'Livrée' },
];

export function resumeCommande(lignes: { quantite: number; produit?: { nom: string } | null; nomLibre?: string | null }[]): string {
  if (lignes.length === 0) return '—';
  const parts = lignes.map((l) => {
    const nom = l.produit?.nom ?? l.nomLibre ?? 'Article';
    return `${l.quantite} × ${nom}`;
  });
  const text = parts.join(', ');
  return text.length > 72 ? `${text.slice(0, 69)}…` : text;
}

export function libelleRoleCommandes(role: Role | undefined): string {
  if (!role) return COMMANDES_COPY.list.title.ADMIN;
  return COMMANDES_COPY.list.title[role];
}

export function sousTitreRoleCommandes(role: Role | undefined): string {
  if (!role) return COMMANDES_COPY.list.subtitle.ADMIN;
  return COMMANDES_COPY.list.subtitle[role];
}

export function messageListeVide(role: Role | undefined): string {
  if (!role) return COMMANDES_COPY.list.empty.ADMIN;
  return COMMANDES_COPY.list.empty[role];
}

import { statutLabels } from '../lib/api';
import { workflowSteps } from '../lib/commandesCopy';
import type { StatutCommande } from '../types';

const activeOrder: StatutCommande[] = [
  'EN_ATTENTE',
  'EN_PREPARATION',
  'EXPEDIEE',
  'LIVREE',
];

export function CommandeWorkflow({ statut }: { statut: StatutCommande }) {
  if (statut === 'ANNULEE') {
    return (
      <p className="commande-workflow-cancelled">
        Commande <strong>annulée</strong>
      </p>
    );
  }

  const currentIndex = activeOrder.indexOf(statut);

  return (
    <ol className="commande-workflow" aria-label="Avancement de la commande">
      {workflowSteps.map((step, index) => {
        const done = index < currentIndex;
        const current = index === currentIndex;
        const upcoming = index > currentIndex;

        return (
          <li
            key={step.key}
            className={`commande-workflow-step ${done ? 'done' : ''} ${current ? 'current' : ''} ${upcoming ? 'upcoming' : ''}`}
            aria-current={current ? 'step' : undefined}
          >
            <span className="commande-workflow-dot" aria-hidden />
            <span className="commande-workflow-label">{step.label}</span>
            {current && (
              <span className="commande-workflow-status">{statutLabels[statut]}</span>
            )}
          </li>
        );
      })}
    </ol>
  );
}

import { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { commandesApi } from '../lib/api';
import {
  COMMANDES_COPY,
  libelleRoleCommandes,
  messageListeVide,
  resumeCommande,
  sousTitreRoleCommandes,
} from '../lib/commandesCopy';
import { PageHeader, StatusBadge } from '../components/UI';
import type { Commande } from '../types';

export function CommandesPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [commandes, setCommandes] = useState<Commande[]>([]);
  const [error, setError] = useState('');

  useEffect(() => {
    commandesApi
      .list()
      .then(setCommandes)
      .catch((err) => setError(err.message));
  }, []);

  const copy = COMMANDES_COPY.list;

  return (
    <>
      <PageHeader
        title={libelleRoleCommandes(user?.role)}
        subtitle={sousTitreRoleCommandes(user?.role)}
        action={
          user?.role === 'MAGASIN' ? (
            <Link to="/nouvelle-commande" className="btn btn-primary">
              Nouvelle commande
            </Link>
          ) : undefined
        }
      />

      {error && <p className="error-text">{error}</p>}

      <section className="panel">
        {commandes.length === 0 ? (
          <div className="commandes-empty">
            <p className="muted">{messageListeVide(user?.role)}</p>
            {user?.role === 'MAGASIN' && (
              <Link to="/nouvelle-commande" className="btn btn-primary">
                Nouvelle commande
              </Link>
            )}
          </div>
        ) : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>{copy.columns.numero}</th>
                  {user?.role !== 'MAGASIN' && <th>{copy.columns.magasin}</th>}
                  <th>{copy.columns.date}</th>
                  <th>{copy.columns.articles}</th>
                  <th>{copy.columns.annotations}</th>
                  <th>{copy.columns.statut}</th>
                </tr>
              </thead>
              <tbody>
                {commandes.map((commande) => (
                  <tr
                    key={commande.id}
                    className="clickable-row"
                    onClick={() => navigate(`/commandes/${commande.id}`)}
                  >
                    <td><strong>{commande.numero}</strong></td>
                    {user?.role !== 'MAGASIN' && <td>{commande.magasin?.nom}</td>}
                    <td>{new Date(commande.createdAt).toLocaleString('fr-FR')}</td>
                    <td className="commande-resume-cell">
                      <span className="commande-resume-count">
                        {commande.lignes.length} article{commande.lignes.length > 1 ? 's' : ''}
                      </span>
                      <span className="commande-resume-detail muted">
                        {resumeCommande(commande.lignes)}
                      </span>
                    </td>
                    <td>
                      {commande.notes
                        ? `${commande.notes.slice(0, 48)}${commande.notes.length > 48 ? '…' : ''}`
                        : '—'}
                    </td>
                    <td><StatusBadge statut={commande.statut} /></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </>
  );
}

import { FormEvent, useEffect, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { CommandeWorkflow } from '../components/CommandeWorkflow';
import { useAuth } from '../context/AuthContext';
import { commandesApi, produitsApi } from '../lib/api';
import { COMMANDES_COPY, statutActionLabel } from '../lib/commandesCopy';
import { PageHeader, StatusBadge } from '../components/UI';
import type { Commande, LigneCommande, LigneCommandeInput, Produit, StatutCommande } from '../types';
import { ligneCategorie, ligneLabel } from '../types';

const nextStatut: Partial<Record<StatutCommande, StatutCommande>> = {
  EN_ATTENTE: 'EN_PREPARATION',
  EN_PREPARATION: 'EXPEDIEE',
  EXPEDIEE: 'LIVREE',
};

const editableStatuts: StatutCommande[] = ['EN_ATTENTE', 'EN_PREPARATION', 'EXPEDIEE'];

type EditLigne = {
  key: string;
  produitId?: string;
  nomLibre?: string;
  nom: string;
  categorie: string;
  quantite: number;
};

const copy = COMMANDES_COPY.detail;

function toEditLigne(ligne: LigneCommande): EditLigne {
  return {
    key: ligne.id,
    produitId: ligne.produitId ?? undefined,
    nomLibre: ligne.nomLibre ?? undefined,
    nom: ligneLabel(ligne),
    categorie: ligneCategorie(ligne),
    quantite: ligne.quantite,
  };
}

function toLigneInput(ligne: EditLigne): LigneCommandeInput {
  if (ligne.produitId) {
    return { produitId: ligne.produitId, quantite: ligne.quantite };
  }
  return { nomLibre: ligne.nomLibre ?? ligne.nom, quantite: ligne.quantite };
}

export function CommandeDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();

  const [commande, setCommande] = useState<Commande | null>(null);
  const [produits, setProduits] = useState<Produit[]>([]);
  const [annotations, setAnnotations] = useState('');
  const [editLignes, setEditLignes] = useState<EditLigne[]>([]);
  const [addProduitId, setAddProduitId] = useState('');
  const [addLibreNom, setAddLibreNom] = useState('');
  const [error, setError] = useState('');
  const [saving, setSaving] = useState(false);
  const [loadingStatut, setLoadingStatut] = useState(false);

  const canManage = user?.role === 'PRODUCTION' || user?.role === 'ADMIN';
  const canAnnotate = Boolean(commande && commande.statut !== 'LIVREE' && commande.statut !== 'ANNULEE');

  useEffect(() => {
    if (!id) return;

    Promise.all([commandesApi.get(id), produitsApi.list()])
      .then(([data, catalog]) => {
        setCommande(data);
        setAnnotations(data.notes ?? '');
        setEditLignes(data.lignes.map(toEditLigne));
        setProduits(catalog);
      })
      .catch((err) => setError(err.message));
  }, [id]);

  async function saveAnnotations(event: FormEvent) {
    event.preventDefault();
    if (!commande) return;

    setSaving(true);
    setError('');
    try {
      const updated = await commandesApi.update(commande.id, { notes: annotations });
      setCommande(updated);
      setAnnotations(updated.notes ?? '');
    } catch (err) {
      setError(err instanceof Error ? err.message : COMMANDES_COPY.errors.generic);
    } finally {
      setSaving(false);
    }
  }

  async function saveCommande(event: FormEvent) {
    event.preventDefault();
    if (!commande || !canManage) return;

    const lignes = editLignes
      .filter((ligne) => ligne.quantite > 0)
      .map(toLigneInput);

    if (lignes.length === 0) {
      setError(COMMANDES_COPY.errors.atLeastOneWithQty);
      return;
    }

    setSaving(true);
    setError('');
    try {
      const updated = await commandesApi.update(commande.id, {
        lignes,
        notes: annotations || undefined,
      });
      setCommande(updated);
      setAnnotations(updated.notes ?? '');
      setEditLignes(updated.lignes.map(toEditLigne));
    } catch (err) {
      setError(err instanceof Error ? err.message : COMMANDES_COPY.errors.generic);
    } finally {
      setSaving(false);
    }
  }

  function addProductLine() {
    if (!addProduitId) return;
    const produit = produits.find((p) => p.id === addProduitId);
    if (!produit) return;

    if (editLignes.some((ligne) => ligne.produitId === produit.id)) {
      setError(COMMANDES_COPY.errors.alreadyInOrder);
      return;
    }

    setEditLignes((items) => [
      ...items,
      {
        key: crypto.randomUUID(),
        produitId: produit.id,
        nom: produit.nom,
        categorie: produit.categorie,
        quantite: 1,
      },
    ]);
    setAddProduitId('');
    setError('');
  }

  function addLibreLine() {
    const nom = addLibreNom.trim();
    if (!nom) {
      setError(COMMANDES_COPY.errors.articleNameRequired);
      return;
    }

    setEditLignes((items) => [
      ...items,
      {
        key: crypto.randomUUID(),
        nomLibre: nom,
        nom,
        categorie: copy.horsCatalogue,
        quantite: 1,
      },
    ]);
    setAddLibreNom('');
    setError('');
  }

  async function advanceStatut() {
    if (!commande) return;
    const next = nextStatut[commande.statut];
    if (!next) return;

    setLoadingStatut(true);
    setError('');
    try {
      await commandesApi.updateStatut(commande.id, next);
      if (next === 'LIVREE') {
        navigate('/commandes');
      } else {
        const updated = await commandesApi.get(commande.id);
        setCommande(updated);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : COMMANDES_COPY.errors.generic);
    } finally {
      setLoadingStatut(false);
    }
  }

  if (!commande) {
    return (
      <>
        <PageHeader title={copy.loadingTitle} subtitle={copy.loadingSubtitle} />
        {error && <p className="error-text">{error}</p>}
      </>
    );
  }

  const availableProduits = produits.filter(
    (p) => !editLignes.some((ligne) => ligne.produitId === p.id),
  );
  const next = nextStatut[commande.statut];

  return (
    <>
      <PageHeader
        title={`Commande ${commande.numero}`}
        subtitle={commande.magasin ? `${copy.fields.magasin} : ${commande.magasin.nom}` : undefined}
        action={
          <Link to="/commandes" className="btn btn-secondary">
            {copy.back}
          </Link>
        }
      />

      {error && <p className="error-text">{error}</p>}

      <section className="panel commande-workflow-panel">
        <h2>{copy.sections.workflow}</h2>
        <CommandeWorkflow statut={commande.statut} />
        {canManage && next && (
          <button
            type="button"
            className="btn btn-primary commande-status-action"
            disabled={loadingStatut}
            onClick={advanceStatut}
          >
            {loadingStatut ? copy.updatingStatus : statutActionLabel(next)}
          </button>
        )}
      </section>

      <div className="grid-2">
        <section className="panel">
          <h2>{copy.sections.infos}</h2>
          <dl className="detail-list">
            <div>
              <dt>{copy.fields.numero}</dt>
              <dd>{commande.numero}</dd>
            </div>
            <div>
              <dt>{copy.fields.date}</dt>
              <dd>{new Date(commande.createdAt).toLocaleString('fr-FR')}</dd>
            </div>
            <div>
              <dt>{copy.fields.magasin}</dt>
              <dd>{commande.magasin?.nom ?? '—'}</dd>
            </div>
            <div>
              <dt>{copy.fields.statut}</dt>
              <dd><StatusBadge statut={commande.statut} /></dd>
            </div>
          </dl>
        </section>

        <section className="panel form-panel">
          <h2>{copy.sections.annotations}</h2>
          <p className="muted panel-intro">{copy.annotationsHint}</p>
          <form onSubmit={saveAnnotations}>
            <label>
              {copy.fields.annotations}
              <textarea
                rows={5}
                value={annotations}
                onChange={(e) => setAnnotations(e.target.value)}
                disabled={!canAnnotate}
                placeholder={copy.annotationsPlaceholder}
              />
            </label>
            {canAnnotate && (
              <button type="submit" className="btn btn-primary" disabled={saving}>
                {saving ? copy.saving : copy.saveAnnotations}
              </button>
            )}
          </form>
        </section>
      </div>

      <section className="panel">
        <h2>{copy.sections.articles}</h2>
        {canManage && editableStatuts.includes(commande.statut) ? (
          <form onSubmit={saveCommande} className="form-panel">
            <p className="muted panel-intro">{copy.articlesIntroProduction}</p>

            <div className="add-product-row">
              <label>
                {copy.addCatalogue}
                <select value={addProduitId} onChange={(e) => setAddProduitId(e.target.value)}>
                  <option value="">{copy.selectArticle}</option>
                  {availableProduits.map((produit) => (
                    <option key={produit.id} value={produit.id}>
                      {produit.nom} ({produit.categorie})
                    </option>
                  ))}
                </select>
              </label>
              <button
                type="button"
                className="btn btn-secondary"
                disabled={!addProduitId}
                onClick={addProductLine}
              >
                {copy.add}
              </button>
            </div>

            <div className="add-product-row">
              <label>
                {copy.addHorsCatalogue}
                <input
                  type="text"
                  value={addLibreNom}
                  onChange={(e) => setAddLibreNom(e.target.value)}
                  placeholder={copy.articleNamePlaceholder}
                />
              </label>
              <button
                type="button"
                className="btn btn-secondary"
                disabled={!addLibreNom.trim()}
                onClick={addLibreLine}
              >
                {copy.add}
              </button>
            </div>

            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>{copy.columns.article}</th>
                    <th>{copy.columns.categorie}</th>
                    <th>{copy.columns.quantite}</th>
                    <th></th>
                  </tr>
                </thead>
                <tbody>
                  {editLignes.map((ligne, index) => (
                    <tr key={ligne.key}>
                      <td><strong>{ligne.nom}</strong></td>
                      <td>{ligne.categorie}</td>
                      <td>
                        <input
                          type="number"
                          min="0"
                          step="1"
                          value={ligne.quantite}
                          onChange={(e) =>
                            setEditLignes((items) =>
                              items.map((item, i) =>
                                i === index ? { ...item, quantite: Number(e.target.value) } : item,
                              ),
                            )
                          }
                        />
                      </td>
                      <td>
                        <button
                          type="button"
                          className="btn btn-secondary btn-sm"
                          onClick={() =>
                            setEditLignes((items) => items.filter((_, i) => i !== index))
                          }
                        >
                          {copy.remove}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <button type="submit" className="btn btn-primary" disabled={saving}>
              {saving ? copy.saving : copy.saveArticles}
            </button>
          </form>
        ) : (
          <>
            <p className="muted panel-intro">{copy.articlesIntroReadonly}</p>
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>{copy.columns.article}</th>
                    <th>{copy.columns.categorie}</th>
                    <th>{copy.columns.prixUnitaire}</th>
                    <th>{copy.columns.quantite}</th>
                    <th>{copy.columns.total}</th>
                  </tr>
                </thead>
                <tbody>
                  {commande.lignes.map((ligne) => (
                    <tr key={ligne.id}>
                      <td><strong>{ligneLabel(ligne)}</strong></td>
                      <td>{ligneCategorie(ligne)}</td>
                      <td>{ligne.produit ? `${ligne.produit.prix.toFixed(2)} €` : copy.noPrice}</td>
                      <td>{ligne.quantite}</td>
                      <td>
                        {ligne.produit
                          ? `${(ligne.produit.prix * ligne.quantite).toFixed(2)} €`
                          : '—'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}
      </section>
    </>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { commandesApi, produitsApi } from '../lib/api';
import { COMMANDES_COPY } from '../lib/commandesCopy';
import { PageHeader } from '../components/UI';
import type { LigneCommandeInput, Produit } from '../types';

type LigneLibre = { id: string; nom: string; quantite: number };

const copy = COMMANDES_COPY.new;
const errors = COMMANDES_COPY.errors;

export function NouvelleCommandePage() {
  const navigate = useNavigate();
  const [produits, setProduits] = useState<Produit[]>([]);
  const [search, setSearch] = useState('');
  const [quantites, setQuantites] = useState<Record<string, number>>({});
  const [lignesLibres, setLignesLibres] = useState<LigneLibre[]>([]);
  const [libreNom, setLibreNom] = useState('');
  const [libreQuantite, setLibreQuantite] = useState(1);
  const [notes, setNotes] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    produitsApi
      .list()
      .then(setProduits)
      .catch((err) => setError(err.message));
  }, []);

  const filteredProduits = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) return produits;
    return produits.filter(
      (p) =>
        p.nom.toLowerCase().includes(query) ||
        p.categorie.toLowerCase().includes(query),
    );
  }, [produits, search]);

  const selectedCatalogueCount = Object.values(quantites).filter((q) => q > 0).length;

  function addLigneLibre() {
    const nom = libreNom.trim();
    if (!nom) {
      setError(errors.articleNameRequired);
      return;
    }
    if (libreQuantite <= 0) {
      setError(errors.quantityPositive);
      return;
    }

    setLignesLibres((items) => [
      ...items,
      { id: crypto.randomUUID(), nom, quantite: libreQuantite },
    ]);
    setLibreNom('');
    setLibreQuantite(1);
    setError('');
  }

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();

    const lignesCatalogue: LigneCommandeInput[] = Object.entries(quantites)
      .filter(([, quantite]) => quantite > 0)
      .map(([produitId, quantite]) => ({ produitId, quantite }));

    const lignesHorsCatalogue: LigneCommandeInput[] = lignesLibres.map(({ nom, quantite }) => ({
      nomLibre: nom,
      quantite,
    }));

    const lignes = [...lignesCatalogue, ...lignesHorsCatalogue];

    if (lignes.length === 0) {
      setError(errors.atLeastOneArticle);
      return;
    }

    setLoading(true);
    setError('');

    try {
      await commandesApi.create({ lignes, notes: notes || undefined });
      navigate('/commandes');
    } catch (err) {
      setError(err instanceof Error ? err.message : errors.generic);
    } finally {
      setLoading(false);
    }
  }

  return (
    <>
      <PageHeader title={copy.title} subtitle={copy.subtitle} />

      {error && <p className="error-text">{error}</p>}

      <form onSubmit={handleSubmit} className="panel form-panel commande-form">
        <section className="commande-form-section">
          <h2>{copy.catalogue}</h2>
          <label>
            {copy.search}
            <input
              type="search"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder={copy.searchPlaceholder}
            />
          </label>

          {selectedCatalogueCount > 0 && (
            <p className="commande-form-summary">
              {selectedCatalogueCount} article{selectedCatalogueCount > 1 ? 's' : ''} sélectionné{selectedCatalogueCount > 1 ? 's' : ''} dans le catalogue
            </p>
          )}

          <div className="product-order-grid">
            {filteredProduits.map((produit) => (
              <label key={produit.id} className="product-order-card">
                <div>
                  <strong>{produit.nom}</strong>
                  <span>{produit.categorie} — {produit.prix.toFixed(2)} €</span>
                </div>
                <input
                  type="number"
                  min="0"
                  step="1"
                  placeholder="0"
                  aria-label={`Quantité pour ${produit.nom}`}
                  value={quantites[produit.id] ?? ''}
                  onChange={(e) =>
                    setQuantites((prev) => ({
                      ...prev,
                      [produit.id]: Number(e.target.value) || 0,
                    }))
                  }
                />
              </label>
            ))}
          </div>

          {filteredProduits.length === 0 && (
            <p className="muted">{copy.emptySearch}</p>
          )}
        </section>

        <section className="custom-lines-section commande-form-section">
          <h2>{copy.horsCatalogue}</h2>
          <p className="muted panel-intro">{copy.horsCatalogueIntro}</p>

          <div className="add-product-row">
            <label>
              {copy.articleName}
              <input
                type="text"
                value={libreNom}
                onChange={(e) => setLibreNom(e.target.value)}
                placeholder={copy.articleNamePlaceholder}
              />
            </label>
            <label>
              {copy.quantite}
              <input
                type="number"
                min="1"
                step="1"
                value={libreQuantite}
                onChange={(e) => setLibreQuantite(Number(e.target.value) || 1)}
              />
            </label>
            <button type="button" className="btn btn-secondary" onClick={addLigneLibre}>
              {copy.add}
            </button>
          </div>

          {lignesLibres.length > 0 && (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>Article</th>
                    <th>Quantité</th>
                    <th></th>
                  </tr>
                </thead>
                <tbody>
                  {lignesLibres.map((ligne) => (
                    <tr key={ligne.id}>
                      <td><strong>{ligne.nom}</strong></td>
                      <td>{ligne.quantite}</td>
                      <td>
                        <button
                          type="button"
                          className="btn btn-secondary btn-sm"
                          onClick={() =>
                            setLignesLibres((items) => items.filter((item) => item.id !== ligne.id))
                          }
                        >
                          {copy.remove}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>

        <section className="commande-form-section">
          <h2>{copy.annotations}</h2>
          <p className="muted panel-intro">{copy.annotationsHint}</p>
          <label>
            {copy.annotations}
            <textarea
              rows={3}
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder={copy.annotationsPlaceholder}
            />
          </label>
        </section>

        <button type="submit" className="btn btn-primary" disabled={loading}>
          {loading ? copy.submitting : copy.submit}
        </button>
      </form>
    </>
  );
}

