import { useEffect, useMemo, useState } from 'react';
import { produitsApi } from '../lib/api';
import { AddProduitForm } from '../components/AddForms';
import { PageHeader } from '../components/UI';
import type { Produit } from '../types';

export function CataloguePage() {
  const [produits, setProduits] = useState<Produit[]>([]);
  const [search, setSearch] = useState('');
  const [categorie, setCategorie] = useState('');
  const [error, setError] = useState('');
  const [addOpen, setAddOpen] = useState(false);

  async function load() {
    setProduits(await produitsApi.list());
  }

  useEffect(() => {
    load().catch((err) => setError(err.message));
  }, []);

  const categories = useMemo(
    () => [...new Set(produits.map((p) => p.categorie))].sort((a, b) => a.localeCompare(b, 'fr')),
    [produits],
  );

  const filtered = useMemo(() => {
    const query = search.trim().toLowerCase();
    return produits.filter((produit) => {
      if (categorie && produit.categorie !== categorie) return false;
      if (!query) return true;
      return (
        produit.nom.toLowerCase().includes(query) ||
        produit.categorie.toLowerCase().includes(query) ||
        (produit.description?.toLowerCase().includes(query) ?? false)
      );
    });
  }, [produits, search, categorie]);

  const grouped = useMemo(() => {
    const map = new Map<string, Produit[]>();
    for (const produit of filtered) {
      const list = map.get(produit.categorie) ?? [];
      list.push(produit);
      map.set(produit.categorie, list);
    }
    return [...map.entries()].sort(([a], [b]) => a.localeCompare(b, 'fr'));
  }, [filtered]);

  return (
    <>
      <PageHeader
        title="Catalogue produits"
        subtitle="Référentiel des produits finis proposés aux magasins pour leurs commandes."
        action={
          <button type="button" className="btn btn-primary" onClick={() => setAddOpen(true)}>
            + Nouveau produit
          </button>
        }
      />

      {error && !addOpen && <p className="error-text">{error}</p>}

      <div className="stats-grid catalogue-stats">
        <div className="stat-card">
          <span className="stat-label">Produits au catalogue</span>
          <span className="stat-value">{produits.length}</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Familles</span>
          <span className="stat-value">{categories.length}</span>
        </div>
        <div className="stat-card stat-card-info">
          <span className="stat-label">Résultats affichés</span>
          <span className="stat-value">{filtered.length}</span>
        </div>
      </div>

      <section className="panel catalogue-toolbar">
        <label className="inventaire-search">
          <span className="sr-only">Rechercher</span>
          <input
            type="search"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="🔍  Nom, catégorie ou description…"
          />
        </label>
        <div className="inventaire-filters">
          <button
            type="button"
            className={`filter-chip ${!categorie ? 'active' : ''}`}
            onClick={() => setCategorie('')}
          >
            Toutes les catégories
          </button>
          {categories.map((cat) => (
            <button
              key={cat}
              type="button"
              className={`filter-chip ${categorie === cat ? 'active' : ''}`}
              onClick={() => setCategorie((c) => (c === cat ? '' : cat))}
            >
              {cat}
            </button>
          ))}
        </div>
      </section>

      <section className="panel">
        {filtered.length === 0 ? (
          <div className="catalogue-empty">
            <p className="muted">
              {produits.length === 0
                ? 'Aucun produit au catalogue. Ajoutez le premier produit.'
                : 'Aucun produit ne correspond à votre recherche.'}
            </p>
            {produits.length === 0 && (
              <button type="button" className="btn btn-primary" onClick={() => setAddOpen(true)}>
                + Nouveau produit
              </button>
            )}
          </div>
        ) : (
          grouped.map(([cat, items]) => (
            <div key={cat} className="catalogue-group">
              <h2>{cat}</h2>
              <div className="table-wrap">
                <table className="catalogue-table">
                  <thead>
                    <tr>
                      <th>Produit</th>
                      <th>Description</th>
                      <th>Prix</th>
                      <th>Unité</th>
                    </tr>
                  </thead>
                  <tbody>
                    {items.map((produit) => (
                      <tr key={produit.id}>
                        <td><strong>{produit.nom}</strong></td>
                        <td className="catalogue-desc">{produit.description ?? '—'}</td>
                        <td>{produit.prix.toFixed(2)} €</td>
                        <td>{produit.unite}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          ))
        )}
      </section>

      {addOpen && (
        <div className="modal-overlay" onClick={() => setAddOpen(false)}>
          <div
            className="modal-panel"
            role="dialog"
            aria-labelledby="catalogue-add-title"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="modal-header">
              <h2 id="catalogue-add-title">Nouveau produit</h2>
              <button
                type="button"
                className="modal-close"
                onClick={() => setAddOpen(false)}
                aria-label="Fermer"
              >
                ×
              </button>
            </div>
            <AddProduitForm
              onAdded={() => {
                load().catch((err) => setError(err.message));
                setAddOpen(false);
              }}
            />
          </div>
        </div>
      )}
    </>
  );
}

