import { Router } from 'express';
import prisma from '../lib/prisma.js';
import { authenticate, authorize } from '../middleware/auth.js';

const router = Router();

router.use(authenticate);

router.get('/', async (_req, res) => {
  const produits = await prisma.produit.findMany({
    where: { actif: true },
    orderBy: [{ categorie: 'asc' }, { nom: 'asc' }],
  });
  res.json(produits);
});

router.post('/', authorize('ADMIN', 'PRODUCTION'), async (req, res) => {
  const { nom, description, categorie, prix, unite } = req.body;

  if (!nom?.trim() || !categorie?.trim() || prix == null) {
    return res.status(400).json({ error: 'Nom, catégorie et prix requis' });
  }

  const produit = await prisma.produit.create({
    data: {
      nom: nom.trim(),
      description: description?.trim() || null,
      categorie: categorie.trim(),
      prix: Number(prix),
      unite: unite?.trim() || 'pièce',
    },
  });

  await prisma.stockProductionProduit.create({
    data: { produitId: produit.id },
  });

  res.status(201).json(produit);
});

router.patch('/:id', authorize('ADMIN', 'PRODUCTION'), async (req, res) => {
  const { nom, description, categorie, prix, unite } = req.body;

  const existing = await prisma.produit.findUnique({ where: { id: req.params.id } });
  if (!existing) {
    return res.status(404).json({ error: 'Produit introuvable' });
  }

  if (nom !== undefined && !nom?.trim()) {
    return res.status(400).json({ error: 'Le nom du produit est requis' });
  }
  if (categorie !== undefined && !categorie?.trim()) {
    return res.status(400).json({ error: 'La catégorie est requise' });
  }
  if (prix !== undefined && (Number.isNaN(Number(prix)) || Number(prix) < 0)) {
    return res.status(400).json({ error: 'Le prix doit être un nombre positif' });
  }

  const produit = await prisma.produit.update({
    where: { id: existing.id },
    data: {
      ...(nom !== undefined && { nom: nom.trim() }),
      ...(description !== undefined && { description: description?.trim() || null }),
      ...(categorie !== undefined && { categorie: categorie.trim() }),
      ...(prix !== undefined && { prix: Number(prix) }),
      ...(unite !== undefined && { unite: unite?.trim() || 'pièce' }),
    },
  });

  res.json(produit);
});

router.delete('/:id', authorize('ADMIN', 'PRODUCTION'), async (req, res) => {
  const existing = await prisma.produit.findUnique({ where: { id: req.params.id } });
  if (!existing) {
    return res.status(404).json({ error: 'Produit introuvable' });
  }

  await prisma.produit.update({
    where: { id: existing.id },
    data: { actif: false },
  });

  res.json({ success: true });
});

export default router;

export const PRODUIT_CATEGORIES = [
  'Pain',
  'Viennoiserie',
  'Pâtisserie',
  'Salé',
  'Snacking',
  'Autre',
] as const;

export const PRODUIT_UNITES = ['pièce', 'plateau', 'barquette', 'kg', 'g'] as const;

export type ProduitDraft = {
  nom: string;
  categorie: string;
  categorieCustom: string;
  description: string;
  prix: string;
  unite: string;
};

export function produitToDraft(produit: {
  nom: string;
  categorie: string;
  description?: string | null;
  prix: number;
  unite: string;
}): ProduitDraft {
  const isPreset = (PRODUIT_CATEGORIES as readonly string[]).includes(produit.categorie);
  return {
    nom: produit.nom,
    categorie: isPreset ? produit.categorie : 'Autre',
    categorieCustom: isPreset ? '' : produit.categorie,
    description: produit.description ?? '',
    prix: String(produit.prix),
    unite: produit.unite,
  };
}

export function draftCategorie(draft: ProduitDraft): string {
  return draft.categorie === 'Autre' ? draft.categorieCustom.trim() : draft.categorie;
}

export function draftToPayload(draft: ProduitDraft) {
  const categorie = draftCategorie(draft);
  return {
    nom: draft.nom.trim(),
    categorie,
    description: draft.description.trim() || undefined,
    prix: Number(draft.prix),
    unite: draft.unite.trim() || 'pièce',
  };
}

export function isDraftValid(draft: ProduitDraft): boolean {
  return Boolean(
    draft.nom.trim() &&
      draftCategorie(draft) &&
      draft.prix &&
      !Number.isNaN(Number(draft.prix)) &&
      Number(draft.prix) >= 0,
  );
}

export function isDraftDirty(
  produit: { nom: string; categorie: string; description?: string | null; prix: number; unite: string },
  draft: ProduitDraft,
): boolean {
  const payload = draftToPayload(draft);
  return (
    produit.nom !== payload.nom ||
    produit.categorie !== payload.categorie ||
    (produit.description ?? '') !== (payload.description ?? '') ||
    produit.prix !== payload.prix ||
    produit.unite !== payload.unite
  );
}

export const emptyProduitDraft = (): ProduitDraft => ({
  nom: '',
  categorie: 'Pain',
  categorieCustom: '',
  description: '',
  prix: '',
  unite: 'pièce',
});

