import {
  PRODUIT_CATEGORIES,
  PRODUIT_UNITES,
  type ProduitDraft,
} from '../lib/produitCatalogue';

type ProduitDraftFieldsProps = {
  draft: ProduitDraft;
  onChange: (draft: ProduitDraft) => void;
  idPrefix?: string;
  compact?: boolean;
};

export function ProduitDraftFields({
  draft,
  onChange,
  idPrefix = 'produit',
  compact = false,
}: ProduitDraftFieldsProps) {
  function patch(partial: Partial<ProduitDraft>) {
    onChange({ ...draft, ...partial });
  }

  return (
    <div className={`produit-draft-fields ${compact ? 'produit-draft-fields-compact' : ''}`}>
      <label>
        Nom du produit
        <input
          id={`${idPrefix}-nom`}
          value={draft.nom}
          onChange={(e) => patch({ nom: e.target.value })}
          placeholder="Ex. : Croissant au beurre"
          required
        />
      </label>

      <label>
        Catégorie
        <select
          value={draft.categorie}
          onChange={(e) => patch({ categorie: e.target.value, categorieCustom: '' })}
        >
          {PRODUIT_CATEGORIES.map((cat) => (
            <option key={cat} value={cat}>
              {cat}
            </option>
          ))}
        </select>
      </label>

      {draft.categorie === 'Autre' && (
        <label>
          Catégorie personnalisée
          <input
            value={draft.categorieCustom}
            onChange={(e) => patch({ categorieCustom: e.target.value })}
            placeholder="Ex. : Boisson chaude"
            required
          />
        </label>
      )}

      <label>
        Prix (€)
        <input
          type="number"
          min="0"
          step="0.01"
          value={draft.prix}
          onChange={(e) => patch({ prix: e.target.value })}
          placeholder="0.00"
          required
        />
      </label>

      <label>
        Unité
        <select value={draft.unite} onChange={(e) => patch({ unite: e.target.value })}>
          {PRODUIT_UNITES.map((u) => (
            <option key={u} value={u}>
              {u}
            </option>
          ))}
        </select>
      </label>

      <label className="produit-draft-desc">
        Description
        <textarea
          rows={compact ? 2 : 3}
          value={draft.description}
          onChange={(e) => patch({ description: e.target.value })}
          placeholder="Courte description visible par les magasins…"
        />
      </label>
    </div>
  );
}

import { FormEvent, useEffect, useMemo, useState } from 'react';
import { ProduitDraftFields } from '../components/ProduitDraftFields';
import { produitsApi } from '../lib/api';
import {
  draftToPayload,
  emptyProduitDraft,
  isDraftDirty,
  isDraftValid,
  produitToDraft,
  type ProduitDraft,
} from '../lib/produitCatalogue';
import { PageHeader } from '../components/UI';
import type { Produit } from '../types';

export function CataloguePage() {
  const [produits, setProduits] = useState<Produit[]>([]);
  const [drafts, setDrafts] = useState<Record<string, ProduitDraft>>({});
  const [search, setSearch] = useState('');
  const [categorie, setCategorie] = useState('');
  const [error, setError] = useState('');
  const [toast, setToast] = useState('');
  const [addOpen, setAddOpen] = useState(false);
  const [newDraft, setNewDraft] = useState(emptyProduitDraft);
  const [savingId, setSavingId] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);

  async function load() {
    const data = await produitsApi.list();
    setProduits(data);
    setDrafts(Object.fromEntries(data.map((p) => [p.id, produitToDraft(p)])));
  }

  useEffect(() => {
    load().catch((err) => setError(err.message));
  }, []);

  useEffect(() => {
    if (!toast) return;
    const timer = setTimeout(() => setToast(''), 2500);
    return () => clearTimeout(timer);
  }, [toast]);

  const categories = useMemo(
    () => [...new Set(produits.map((p) => p.categorie))].sort((a, b) => a.localeCompare(b, 'fr')),
    [produits],
  );

  const filtered = useMemo(() => {
    const query = search.trim().toLowerCase();
    return produits.filter((produit) => {
      if (categorie && produit.categorie !== categorie) return false;
      if (!query) return true;
      return (
        produit.nom.toLowerCase().includes(query) ||
        produit.categorie.toLowerCase().includes(query) ||
        (produit.description?.toLowerCase().includes(query) ?? false)
      );
    });
  }, [produits, search, categorie]);

  function updateDraft(id: string, draft: ProduitDraft) {
    setDrafts((prev) => ({ ...prev, [id]: draft }));
  }

  async function saveProduit(produit: Produit) {
    const draft = drafts[produit.id];
    if (!draft || !isDraftValid(draft)) {
      setError('Vérifiez le nom, la catégorie et le prix du produit.');
      return;
    }

    setSavingId(produit.id);
    setError('');
    try {
      const updated = await produitsApi.update(produit.id, draftToPayload(draft));
      setProduits((items) => items.map((p) => (p.id === updated.id ? updated : p)));
      setDrafts((prev) => ({ ...prev, [updated.id]: produitToDraft(updated) }));
      setToast(`« ${updated.nom} » enregistré`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setSavingId(null);
    }
  }

  async function deleteProduit(produit: Produit) {
    if (!window.confirm(`Retirer « ${produit.nom} » du catalogue ?`)) return;

    setSavingId(produit.id);
    setError('');
    try {
      await produitsApi.remove(produit.id);
      setProduits((items) => items.filter((p) => p.id !== produit.id));
      setDrafts((prev) => {
        const next = { ...prev };
        delete next[produit.id];
        return next;
      });
      setToast(`« ${produit.nom} » retiré du catalogue`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setSavingId(null);
    }
  }

  function resetDraft(produit: Produit) {
    setDrafts((prev) => ({ ...prev, [produit.id]: produitToDraft(produit) }));
  }

  async function handleCreate(event: FormEvent) {
    event.preventDefault();
    if (!isDraftValid(newDraft)) {
      setError('Complétez le nom, la catégorie et le prix pour ajouter le produit.');
      return;
    }

    setCreating(true);
    setError('');
    try {
      const created = await produitsApi.create(draftToPayload(newDraft));
      setProduits((items) => [...items, created].sort((a, b) => a.nom.localeCompare(b.nom, 'fr')));
      setDrafts((prev) => ({ ...prev, [created.id]: produitToDraft(created) }));
      setNewDraft(emptyProduitDraft());
      setAddOpen(false);
      setToast(`« ${created.nom} » ajouté au catalogue`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setCreating(false);
    }
  }

  return (
    <>
      <PageHeader
        title="Catalogue produits"
        subtitle="Modifiez directement chaque fiche produit — les magasins voient ces informations lors de leurs commandes."
        action={
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => setAddOpen((open) => !open)}
          >
            {addOpen ? 'Masquer le formulaire' : '+ Nouveau produit'}
          </button>
        }
      />

      {toast && <p className="toast-banner">{toast}</p>}
      {error && <p className="error-text">{error}</p>}

      {addOpen && (
        <section className="panel form-panel catalogue-add-panel">
          <h2>Ajouter un produit</h2>
          <p className="muted panel-intro">
            Renseignez la fiche ci-dessous, puis validez pour l’ajouter au catalogue.
          </p>
          <form onSubmit={handleCreate}>
            <ProduitDraftFields draft={newDraft} onChange={setNewDraft} idPrefix="new-produit" />
            <div className="catalogue-row-actions">
              <button type="submit" className="btn btn-primary" disabled={creating}>
                {creating ? 'Ajout en cours…' : 'Ajouter au catalogue'}
              </button>
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setNewDraft(emptyProduitDraft())}
              >
                Effacer
              </button>
            </div>
          </form>
        </section>
      )}

      <div className="stats-grid catalogue-stats">
        <div className="stat-card">
          <span className="stat-label">Produits actifs</span>
          <span className="stat-value">{produits.length}</span>
        </div>
        <div className="stat-card">
          <span className="stat-label">Familles</span>
          <span className="stat-value">{categories.length}</span>
        </div>
        <div className="stat-card stat-card-info">
          <span className="stat-label">Affichés</span>
          <span className="stat-value">{filtered.length}</span>
        </div>
      </div>

      <section className="panel catalogue-toolbar">
        <label className="inventaire-search">
          <span className="sr-only">Rechercher</span>
          <input
            type="search"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="🔍  Rechercher un produit…"
          />
        </label>
        <div className="inventaire-filters">
          <button
            type="button"
            className={`filter-chip ${!categorie ? 'active' : ''}`}
            onClick={() => setCategorie('')}
          >
            Toutes
          </button>
          {categories.map((cat) => (
            <button
              key={cat}
              type="button"
              className={`filter-chip ${categorie === cat ? 'active' : ''}`}
              onClick={() => setCategorie((c) => (c === cat ? '' : cat))}
            >
              {cat}
            </button>
          ))}
        </div>
      </section>

      <section className="panel catalogue-editor-panel">
        <div className="catalogue-editor-head">
          <h2>Fiches produits</h2>
          <p className="muted panel-intro">
            Chaque carte est modifiable. Enregistrez vos changements ou annulez pour revenir à la version précédente.
          </p>
        </div>

        {filtered.length === 0 ? (
          <div className="catalogue-empty">
            <p className="muted">
              {produits.length === 0
                ? 'Le catalogue est vide. Ajoutez votre premier produit.'
                : 'Aucun produit ne correspond à votre recherche.'}
            </p>
          </div>
        ) : (
          <div className="catalogue-editor-grid">
            {filtered.map((produit) => {
              const draft = drafts[produit.id] ?? produitToDraft(produit);
              const dirty = isDraftDirty(produit, draft);
              const saving = savingId === produit.id;

              return (
                <article
                  key={produit.id}
                  className={`catalogue-editor-card ${dirty ? 'catalogue-editor-card-dirty' : ''} ${saving ? 'catalogue-editor-card-saving' : ''}`}
                >
                  <div className="catalogue-editor-card-head">
                    <span className="category-badge">{draft.categorie === 'Autre' ? draft.categorieCustom || 'Autre' : draft.categorie}</span>
                    {dirty && <span className="catalogue-dirty-badge">Modifié</span>}
                  </div>

                  <ProduitDraftFields
                    draft={draft}
                    onChange={(next) => updateDraft(produit.id, next)}
                    idPrefix={`produit-${produit.id}`}
                    compact
                  />

                  <div className="catalogue-row-actions">
                    <button
                      type="button"
                      className="btn btn-primary btn-sm"
                      disabled={!dirty || saving || !isDraftValid(draft)}
                      onClick={() => saveProduit(produit)}
                    >
                      {saving ? 'Enregistrement…' : 'Enregistrer'}
                    </button>
                    <button
                      type="button"
                      className="btn btn-secondary btn-sm"
                      disabled={!dirty || saving}
                      onClick={() => resetDraft(produit)}
                    >
                      Annuler
                    </button>
                    <button
                      type="button"
                      className="btn btn-secondary btn-sm catalogue-delete-btn"
                      disabled={saving}
                      onClick={() => deleteProduit(produit)}
                    >
                      Retirer
                    </button>
                  </div>
                </article>
              );
            })}
          </div>
        )}
      </section>
    </>
  );
}

